 878	                    current = harmony_result[1];
 879	                    result[i] = Some(current);
 880	                } else {
 881	                    break;
 882	                }
 883	            }
 884	        }
 885	
 886	        // Flatten: user's note first, then harmony voices in chain order
 887	        // (closest to user's position first, outward in both directions).
 888	        // Track each entry's arrangement index for fixed SATB port mapping.
 889	        let mut final_result = vec![note];
 890	        let mut arrangement_indices = vec![self.voice_position];
1120	    ///
1121	    /// Picks the closest-to-input harmonies to relocate. Also rewrites
1122	    /// `last_arrangement_indices` based on the post-shift pitch order so
1123	    /// downstream code (apply_octave_mode anchor logic, MIDI routing) sees
1124	    /// the correct SATB slot for each note.
1125	    fn redistribute_for_voice_position(&mut self, notes: &mut [Note]) {
1126	        if notes.len() <= 1 {
1127	            return;
1128	        }
1129	        let input_midi = u8::from(notes[0]) as i16;
1130	        let voice_position = self.voice_position;
1131	        // Number of harmonies that should sit above the user's note.
1132	        let target_above = voice_position.min(notes.len().saturating_sub(1));
1133	
1134	        let mut below_indices: Vec<usize> = Vec::new();
1135	        let mut above_indices: Vec<usize> = Vec::new();
1136	        for (i, n) in notes.iter().enumerate().skip(1) {
1137	            let m = u8::from(*n) as i16;
1138	            if m < input_midi {
1139	                below_indices.push(i);
1140	            } else if m > input_midi {
1141	                above_indices.push(i);
1142	            }
1143	        }
1144	        let cur_above = above_indices.len();
1145	
1146	        if cur_above < target_above {
1147	            // Promote closest-to-input below-harmonies (highest MIDI) up.
1148	            below_indices.sort_by_key(|&i| std::cmp::Reverse(u8::from(notes[i])));
1149	            for &i in below_indices.iter().take(target_above - cur_above) {
1150	                let mut new_midi = u8::from(notes[i]) as i16;
1151	                while new_midi <= input_midi {
1152	                    new_midi += 12;
1153	                    if new_midi > 127 {
1154	                        break;
1155	                    }
1156	                }
1157	                if (0..=127).contains(&new_midi) {
1158	                    if let Ok(n) = Note::try_from(new_midi as u8) {
1159	                        notes[i] = n;
1160	                    }
1161	                }
1162	            }
1163	        } else if cur_above > target_above {
1164	            // Demote closest-to-input above-harmonies (lowest MIDI) down.
1165	            above_indices.sort_by_key(|&i| u8::from(notes[i]));
1166	            for &i in above_indices.iter().take(cur_above - target_above) {
1167	                let mut new_midi = u8::from(notes[i]) as i16;
1168	                while new_midi >= input_midi {
1169	                    new_midi -= 12;
1170	                    if new_midi < 0 {
1171	                        break;
1172	                    }
1173	                }
1174	                if (0..=127).contains(&new_midi) {
1175	                    if let Ok(n) = Note::try_from(new_midi as u8) {
1176	                        notes[i] = n;
1177	                    }
1178	                }
1179	            }
1180	        }
1181	
1182	        // Rewrite arrangement_indices by post-shift pitch order: highest
1183	        // note → slot 0 (soprano), lowest → slot voice_count-1 (bass).
1184	        let mut order: Vec<usize> = (0..notes.len()).collect();
1185	        order.sort_by_key(|&i| std::cmp::Reverse(u8::from(notes[i])));
1186	        let mut arr = vec![0usize; notes.len()];
1187	        for (slot, &idx) in order.iter().enumerate() {
1188	            arr[idx] = slot;
1189	        }
1190	        self.last_arrangement_indices = arr;
1191	    }
