1193	    fn harmonize_explicit_intervals(&mut self, note: Note) -> Vec<Note> {
1194	        let offsets = self
1195	            .scale
1196	            .degree_of(note)
1197	            .and_then(|degree| self.explicit_interval_map.degree_offsets.get(degree))
1198	            .unwrap_or(&self.explicit_interval_map.fallback_offsets);
1199	        let mut result = Vec::with_capacity(self.voice_count.min(offsets.len() + 1));
1200	        result.push(note);
1201	        let anchor = u8::from(note) as i16;
1202	        for &offset in offsets.iter().take(self.voice_count.saturating_sub(1)) {
1203	            let midi = anchor + offset as i16;
1204	            if let Ok(midi) = u8::try_from(midi) {
1205	                if let Ok(generated) = Note::try_from(midi) {
1206	                    result.push(generated);
1207	                }
1208	            }
1209	        }
1210	
1211	        // Route highest pitch to the lowest arrangement index, regardless
1212	        // of result order (`result[0]` must remain the exact player source).
1213	        let mut order: Vec<usize> = (0..result.len()).collect();
1214	        order.sort_by_key(|&index| std::cmp::Reverse(u8::from(result[index])));
1215	        self.last_arrangement_indices = vec![0; result.len()];
1216	        for (slot, &result_index) in order.iter().enumerate() {
1217	            self.last_arrangement_indices[result_index] = slot;
1218	        }
1219	        self.apply_octave_mode(&mut result);
1220	        result
1221	    }
