1223	    fn harmonize_block_chord(&mut self, note: Note) -> Vec<Note> {
1224	        match super::barry_harris::build_voicing(note, &self.scale, self.beat_phase) {
1225	            Some(voicing) => {
1226	                let mut result = Vec::with_capacity(4);
1227	                result.push(note);
1228	                // The block already contains the melody's scale degree,
1229	                // often in another octave. Keep the played note as that
1230	                // chord voice instead of adding a fifth, doubled pitch class.
1231	                let melody_pc = u8::from(note) % 12;
1232	                for &v in &voicing {
1233	                    if u8::from(v) % 12 != melody_pc {
1234	                        result.push(v);
1235	                    }
1235	                    }
1236	                }
1237	                self.last_arrangement_indices = (0..result.len()).collect();
1238	                self.redistribute_for_voice_position(&mut result);
1239	                self.apply_octave_mode(&mut result);
1240	                result
1241	            }
1242	            None => {
1243	                self.last_arrangement_indices = vec![0];
1244	                self.last_port_map = vec![0];
1245	                vec![note]
1246	            }
1247	        }
1248	    }
