1250	    fn harmonize_functional(&mut self, note: Note) -> Vec<Note> {
1251	        let scale_mode = self.scale_mode;
1252	        let tonic = self.key.semitones_from_c();
1253	        if !HarmonicContext::is_compatible_scale(scale_mode) {
1254	            self.last_arrangement_indices = vec![0];
1255	            self.last_port_map = vec![0];
1256	            return vec![note];
1257	        }
1258	        let ctx = self
1259	            .harmonic_context
1260	            .get_or_insert_with(|| HarmonicContext::new(tonic, scale_mode));
1261	        let mut result = match self.mode {
1262	            HarmonyMode::BachChorale => functional::bach_chorale(note, ctx, scale_mode),
1263	            HarmonyMode::FunctionalHarmony => {
1264	                functional::functional_harmony(note, ctx, scale_mode, self.voice_count)
1265	            }
1266	            _ => vec![note],
1267	        };
1268	        self.last_arrangement_indices = (0..result.len()).collect();
1269	        self.redistribute_for_voice_position(&mut result);
1270	        self.last_port_map = self.last_arrangement_indices.clone();
1271	        result
