1274	    /// Returns the beat phase to use for Species 2-4 dispatch.
1275	    /// Prefers the externally-set transport phase; falls back to the
1276	    /// internal synthetic counter so Species 2-4 work without a
1277	    /// running transport. Returns None unconditionally for any mode
1278	    /// other than StrictCounterpoint, or for Species1 (which ignores
1279	    /// phase entirely), so other code paths see no behavior change.
1280	    fn effective_counterpoint_beat_phase(&self) -> Option<f64> {
1281	        if !matches!(self.mode, HarmonyMode::StrictCounterpoint) {
1282	            return self.counterpoint_beat_phase;
1283	        }
1284	        if matches!(self.counterpoint_species, CounterpointSpecies::Species1) {
1285	            return self.counterpoint_beat_phase;
1286	        }
1287	        self.counterpoint_beat_phase
1288	            .or(Some(self.synthetic_beat_counter))
1289	    }
