1291	    /// Harmonizes a single note in a specific direction using the mode's algorithm.
1292	    /// `above`: if true, generate harmony above; if false, generate below.
1293	    /// Used for bidirectional voice position generation.
1294	    fn harmonize_single_directed(
1295	        &mut self,
1296	        note: Note,
1297	        state_index: usize,
1298	        above: bool,
1299	    ) -> Vec<Note> {
1300	        match self.mode {
1301	            HarmonyMode::PassThrough => modes::pass_through(note, &mut self.scale),
1302	            HarmonyMode::DiatonicThirds => {
1303	                modes::diatonic_thirds_directed(note, &mut self.scale, above)
1304	            }
1305	            HarmonyMode::DiatonicFourths => {
1306	                modes::diatonic_fourths_directed(note, &mut self.scale, above)
1307	            }
1308	            HarmonyMode::RandomBelow => modes::random_directed(note, &mut self.scale, above),
1309	            HarmonyMode::RandomBelowNoSeconds => {
1310	                modes::random_no_seconds_directed(note, &mut self.scale, above)
1311	            }
1312	            HarmonyMode::ContraryMotion => {
1313	                if let Some(state) = self.contrary_motion_states.get_mut(state_index) {
1314	                    state.process_directed(&mut self.scale, note, above)
1315	                } else {
1316	                    vec![note]
1317	                }
1318	            }
1319	            HarmonyMode::StrictCounterpoint => {
1320	                // Species 1 is direction-aware via process_directed. Species 2-4
1321	                // rely on beat-phase and use process_with_beat which ignores
1322	                // `above` — we octave-shift the result post-hoc to honor the
1323	                // chain's direction request.
1324	                let species = self.counterpoint_species;
1325	                let beat_phase = self.effective_counterpoint_beat_phase();
1326	                if let Some(state) = self.counterpoint_states.get_mut(state_index) {
1327	                    let result = if matches!(species, CounterpointSpecies::Species1) {
1328	                        state.process_directed(&mut self.scale, note, above)
1329	                    } else {
1330	                        state.process_with_beat(&mut self.scale, note, beat_phase)
1331	                    };
1332	                    if !matches!(species, CounterpointSpecies::Species1) && result.len() > 1 {
1333	                        if let Some(shifted) = Self::octave_shift_to_side(result[1], note, above) {
1334	                            return vec![note, shifted];
1335	                        }
1336	                    }
1337	                    result
1338	                } else {
1339	                    vec![note]
1340	                }
1341	            }
1342	            HarmonyMode::BarryHarris => {
1343	                modes::diatonic_thirds_directed(note, &mut self.scale, above)
1344	            }
1345	            HarmonyMode::FunctionalHarmony | HarmonyMode::BachChorale => {
1346	                modes::diatonic_thirds_directed(note, &mut self.scale, above)
1347	            }
1348	            HarmonyMode::ExplicitIntervals => vec![note],
1349	        }
1350	    }
