1353	    /// Used internally for chained harmony generation.
1354	    fn harmonize_single(&mut self, note: Note, state_index: usize) -> Vec<Note> {
1355	        match self.mode {
1356	            HarmonyMode::PassThrough => modes::pass_through(note, &mut self.scale),
1357	            HarmonyMode::DiatonicThirds => modes::diatonic_thirds(note, &mut self.scale),
1358	            HarmonyMode::DiatonicFourths => modes::diatonic_fourths(note, &mut self.scale),
1359	            HarmonyMode::RandomBelow => modes::random_below(note, &mut self.scale),
1360	            HarmonyMode::RandomBelowNoSeconds => {
1361	                modes::random_below_no_seconds(note, &mut self.scale)
1362	            }
1363	            HarmonyMode::ContraryMotion => {
1364	                if let Some(state) = self.contrary_motion_states.get_mut(state_index) {
1365	                    state.process(&mut self.scale, note)
1366	                } else {
1367	                    vec![note]
1368	                }
1369	            }
1370	            HarmonyMode::StrictCounterpoint => {
1371	                // Dispatch to process_with_beat so Species 2-4 get beat awareness.
1372	                // Species 1 + beat_phase=None is exactly equivalent to process().
1373	                let beat_phase = self.effective_counterpoint_beat_phase();
1374	                if let Some(state) = self.counterpoint_states.get_mut(state_index) {
1375	                    state.process_with_beat(&mut self.scale, note, beat_phase)
1376	                } else {
1377	                    vec![note]
1378	                }
1379	            }
1380	            HarmonyMode::BarryHarris => modes::diatonic_thirds(note, &mut self.scale),
1381	            HarmonyMode::FunctionalHarmony | HarmonyMode::BachChorale => {
1382	                modes::diatonic_thirds(note, &mut self.scale)
1383	            }
1384	            HarmonyMode::ExplicitIntervals => vec![note],
1385	        }
1386	    }
