 402	    /// Replaces the explicit interval map after bounded validation.
 403	    pub fn set_explicit_interval_map(&mut self, map: ExplicitIntervalMap) -> Result<(), String> {
 404	        for (label, offsets) in map
 405	            .degree_offsets
 406	            .iter()
 407	            .enumerate()
 408	            .map(|(index, offsets)| (format!("degree {}", index + 1), offsets))
 409	            .chain(std::iter::once((
 410	                "fallback".to_string(),
 411	                &map.fallback_offsets,
 412	            )))
 413	        {
 414	            if offsets.len() > 7 {
 415	                return Err(format!(
 416	                    "explicit interval {label} supports at most 7 offsets"
 417	                ));
 418	            }
 419	            for (index, &offset) in offsets.iter().enumerate() {
 420	                if offset == 0 || !(-48..=48).contains(&offset) {
 421	                    return Err(format!(
 422	                        "explicit interval {label} offset must be nonzero and between -48 and 48"
 423	                    ));
 424	                }
 425	                if offsets[..index].contains(&offset) {
 426	                    return Err(format!("explicit interval {label} offsets must be unique"));
 427	                }
 428	            }
 429	        }
 430	        self.explicit_interval_map = map;
 431	        self.clear_active_for_reharm();
 432	        Ok(())
 433	    }
