 200	///
 201	/// // Create engine with 4 voices in C major using diatonic thirds
 202	/// let mut engine = HarmonyEngine::with_voices(Key::C, HarmonyMode::DiatonicThirds, 4);
 203	///
 204	/// // Harmonize a note
 205	/// let result = engine.harmonize(Note::C4);
 206	/// // result = [C4, E4, G4, B4] (melody + 3 chained thirds)
