 208	/// // For MIDI routing, use note_on/note_off tracking
 209	/// let notes_on = engine.harmonize_note_on(Note::C4);
 210	/// // ... send notes_on to outputs ...
 211	/// let notes_off = engine.harmonize_note_off(Note::C4);
 212	/// // notes_off contains the same notes as notes_on
 213	/// ```
 214	///
 215	/// # Note-Off Tracking
 216	///
 217	/// For consistent behavior (especially with random modes), use
 218	/// [`harmonize_note_on`](Self::harmonize_note_on) and
 219	/// [`harmonize_note_off`](Self::harmonize_note_off) instead of
 220	/// [`harmonize`](Self::harmonize). This ensures the same harmony notes
 221	/// are released that were pressed.
