 977	    /// Applies octave mode transformation to harmony notes and populates `last_port_map`.
 978	    /// The melody (index 0) is never modified.
 979	    ///
 980	    /// For Mirror mode: each harmony note is duplicated at +1 and -1 octave,
 981	    /// producing 3x harmony notes. Duplicates are appended and their port map
 982	    /// entries point back to the original harmony voice's port index.
 983	    fn apply_octave_mode(&mut self, notes: &mut Vec<Note>) {
 984	        // Port map based on SATB arrangement position (fixed routing).
 985	        // Each note maps to its arrangement index (0=soprano, 1=alto, 2=tenor, 3=bass).
 986	        self.last_port_map = self.last_arrangement_indices.clone();
 987	
 988	        if notes.len() <= 1 || self.octave_mode == OctaveMode::None {
 989	            return;
 990	        }
 991	
 992	        let melody = notes[0];
 993	        let melody_midi = u8::from(melody);
 994	
 995	        // Helper: check if a shifted note would cross the user's anchor.
 996	        // Returns true if the shift is allowed (stays on the correct side).
 997	        let user_midi = melody_midi;
 998	        let voice_pos = self.voice_position;
 999	        let arr_indices = &self.last_arrangement_indices;
1000	        let anchor_ok = |idx: usize, shifted: u8| -> bool {
1001	            if let Some(&harm_arr) = arr_indices.get(idx) {
1002	                if harm_arr < voice_pos {
1003	                    // Must stay above user
1004	                    shifted >= user_midi
1005	                } else if harm_arr > voice_pos {
1006	                    // Must stay below user
1007	                    shifted <= user_midi
1008	                } else {
1009	                    true // same position as user
1010	                }
1011	            } else {
1012	                true
1013	            }
1014	        };
1015	
1016	        let intensity = self.octave_intensity;
1017	        match self.octave_mode {
1018	            OctaveMode::None => {}
1019	            OctaveMode::Spread => {
1020	                for (i, note) in notes.iter_mut().enumerate().skip(1) {
1021	                    let midi = u8::from(*note);
1022	                    // Continuous: per-voice shift = i × intensity × 12.
1023	                    // intensity = 0 → no displacement. intensity = 1 →
1024	                    // full-octave per voice (legacy behavior).
1025	                    let shift = ((i as f32) * intensity * 12.0).round().max(0.0) as u8;
1026	                    let shifted = midi.saturating_add(shift).min(127);
1027	                    if anchor_ok(i, shifted) {
1028	                        if let Ok(new_note) = Note::try_from(shifted) {
1029	                            *note = new_note;
1030	                        }
1031	                    }
1032	                    // If not anchor_ok, leave the note as-is
1033	                }
1034	            }
1035	            OctaveMode::BassTrebleSplit => {
1036	                let shift = (intensity * 12.0).round().max(0.0) as u8;
1037	                for (i, note) in notes.iter_mut().enumerate().skip(1) {
1038	                    let midi = u8::from(*note);
1039	                    let shifted = if midi < user_midi {
1040	                        midi.saturating_sub(shift)
1041	                    } else {
1042	                        midi.saturating_add(shift).min(127)
1043	                    };
1044	                    if anchor_ok(i, shifted) {
1045	                        if let Ok(new_note) = Note::try_from(shifted) {
1046	                            *note = new_note;
1047	                        }
1048	                    }
1049	                }
1050	            }
1051	            OctaveMode::Mirror => {
1052	                let harmony_count = notes.len() - 1;
1053	                let mut duplicates: Vec<(Note, usize)> = Vec::new();
1054	
1055	                for i in 1..=harmony_count {
1056	                    let midi = u8::from(notes[i]);
1057	                    // +1 octave copy (only if it doesn't cross anchor)
1058	                    let up = midi.wrapping_add(12);
1059	                    if up <= 127 && anchor_ok(i, up) {
1060	                        if let Ok(n) = Note::try_from(up) {
1061	                            duplicates.push((n, i));
1062	                        }
1063	                    }
1064	                    // -1 octave copy (only if it doesn't cross anchor)
1065	                    if midi >= 12 && anchor_ok(i, midi - 12) {
1066	                        if let Ok(n) = Note::try_from(midi - 12) {
1067	                            duplicates.push((n, i));
1068	                        }
1069	                    }
1070	                }
1071	
1072	                for (dup_note, original_idx) in duplicates {
1073	                    notes.push(dup_note);
1074	                    let arr_port = if original_idx < self.last_arrangement_indices.len() {
1075	                        self.last_arrangement_indices[original_idx]
1076	                    } else {
1077	                        original_idx
1078	                    };
1079	                    self.last_port_map.push(arr_port);
1080	                }
1081	            }
1082	        }
1083	    }
