1085	    /// Octave-shift `harmony` so it lands on the correct side of `anchor`.
1086	    /// Returns None if no valid shift exists in MIDI range.
1087	    fn octave_shift_to_side(harmony: Note, anchor: Note, above: bool) -> Option<Note> {
1088	        let anchor_midi = u8::from(anchor) as i16;
1089	        let mut harm_midi = u8::from(harmony) as i16;
1090	        let on_correct_side = if above {
1091	            harm_midi > anchor_midi
1092	        } else {
1093	            harm_midi < anchor_midi
1094	        };
1095	        if on_correct_side {
1096	            return Some(harmony);
1097	        }
1098	        if above {
1099	            while harm_midi <= anchor_midi {
1100	                harm_midi += 12;
1101	                if harm_midi > 127 {
1102	                    return None;
1103	                }
1104	            }
1105	        } else {
1106	            while harm_midi >= anchor_midi {
1107	                harm_midi -= 12;
1108	                if harm_midi < 0 {
1109	                    return None;
1110	                }
1111	            }
1112	        }
1113	        Note::try_from(harm_midi as u8).ok()
1114	    }
