1435	        self.last_borrowed_from = self.scale.last_borrowed_from();
1436	        // Store the harmony notes and port map for Note-Off retrieval
1437	        let midi = u8::from(note);
1438	        if result.len() > 1 {
1439	            self.active_notes.insert(midi, result[1..].to_vec());
