1446	    /// Returns the notes to release for a Note-Off.
1447	    ///
1448	    /// Returns the original note plus any harmony notes that were
1449	    /// produced when the corresponding Note-On was processed via
1450	    /// `harmonize_note_on()`.
1451	    ///
1452	    /// # Arguments
1453	    ///
1454	    /// * `note` - The melody note from the Note-Off message
1455	    ///
1456	    /// # Returns
1457	    ///
1458	    /// Vec of notes to release: original note first, tracked harmony notes after.
1459	    /// If no harmony was tracked, returns just the original note.
1460	    /// Returns and clears the queue of harmony notes that need an
1461	    /// explicit Note-Off after an auto-key triggered key change.
1462	    ///
1463	    /// The router calls this after each `harmonize_note_on` so the old
1464	    /// key's stale harmonies get released before the new key's harmonies
1465	    /// take over. Returns an empty Vec when no key change happened.
1466	    pub fn take_pending_releases(&mut self) -> Vec<Note> {
1467	        std::mem::take(&mut self.pending_releases)
1468	    }
