1470	    /// Clear all note-lifecycle bookkeeping after panic, transport stop,
1471	    /// or an input/output-mode transition. Unlike parameter-change
1472	    /// reharmonization, this intentionally does not queue held inputs for
1473	    /// replay: downstream sound has already been silenced.
1474	    pub fn clear_active_notes(&mut self) {
1475	        self.active_notes.clear();
1476	        self.active_port_maps.clear();
1477	        self.pending_releases.clear();
1478	        self.pending_reharm_inputs.clear();
1479	        self.last_port_map.clear();
1480	    }
