1482	    /// Drain the list of input MIDI notes that were held when a
1483	    /// parameter change wiped `active_notes`. The router re-runs
1484	    /// `harmonize_note_on` for each so the new parameters take effect
1485	    /// without dropping the user's held input.
1486	    pub fn take_reharm_inputs(&mut self) -> Vec<u8> {
1487	        std::mem::take(&mut self.pending_reharm_inputs)
1488	    }
1489	
1490	    /// Wipe per-note tracking after a parameter change, but record the
1491	    /// held input MIDI numbers in `pending_reharm_inputs` so the router
1492	    /// can replay them under the new parameters. Replaces the previous
1493	    /// `self.active_notes.clear(); self.active_port_maps.clear();`
1494	    /// idiom in every parameter setter — the user's held inputs no
1495	    /// longer drop on knob changes.
1496	    fn clear_active_for_reharm(&mut self) {
1497	        self.pending_reharm_inputs
1498	            .extend(self.active_notes.keys().copied());
1499	        self.active_notes.clear();
1500	        self.active_port_maps.clear();
1501	    }
