1503	    pub fn harmonize_note_off(&mut self, note: Note) -> Vec<Note> {
1504	        let midi = u8::from(note);
1505	        // Restore the port map that was stored during Note-On
1506	        if let Some(port_map) = self.active_port_maps.remove(&midi) {
1507	            self.last_port_map = port_map;
1508	        } else {
1509	            self.last_port_map = vec![0];
1510	        }
1511	        match self.active_notes.remove(&midi) {
1512	            Some(harmonies) => {
1513	                let mut result = vec![note];
1514	                result.extend(harmonies);
1515	                result
1516	            }
1517	            None => vec![note], // No tracked harmony, just return original
1518	        }
1519	    }
1520	}
