437	
438	#[allow(clippy::too_many_arguments)]
439	fn run_tauri_router(
440	    input_port: usize,
441	    output_ports: &[usize],
442	    engine: Arc<Mutex<HarmonyEngine>>,
443	    routing_mode: contrapunk::harmony::RoutingMode,
444	    is_guitar: bool,
445	    guitar_device: String,
446	    guitar_channel: usize,
447	    guitar_config: GuitarInputConfig,
448	    guitar_config_shared: Arc<Mutex<Option<GuitarInputConfig>>>,
449	    calibration_profile: Option<contrapunk::audio::guitar::GuitarCalibrationProfile>,
450	    live_pipeline_handle: Option<
451	        Arc<Mutex<Option<Arc<Mutex<contrapunk::audio::guitar_input::GuitarInput>>>>>,
452	    >,
453	    tx: mpsc::Sender<Vec<u8>>,
454	    rx: mpsc::Receiver<Vec<u8>>,
455	    input_notes: Arc<Mutex<HashSet<u8>>>,
456	    harmony_notes: Arc<Mutex<HashSet<u8>>>,
457	    borrowed_notes: Arc<Mutex<HashSet<u8>>>,
458	    chord_name: Arc<Mutex<String>>,
459	    stop_signal: Arc<std::sync::atomic::AtomicBool>,
460	    app_handle: AppHandle,
461	    detune_cents: Arc<AtomicI32>,
462	    panic_pending: Arc<std::sync::atomic::AtomicBool>,
463	    synth_tx: mpsc::Sender<SynthEvent>,
464	    voice_outputs: Arc<Mutex<Vec<VoiceOutputTarget>>>,
465	    transport: Arc<Transport>,
466	    companion: Arc<Mutex<crate::companion::Companion>>,
467	) -> anyhow::Result<()> {
468	    // Connect to either Guitar Audio bridge, physical MIDI input, or
469	    // nothing at all (Computer Keyboard virtual input — notes are pushed
470	    // by inject_note_on/off commands via the shared router_tx).
471	    let _midi_conn;
472	    let _guitar_bridge;
473	    let is_keyboard = input_port == VIRTUAL_COMPUTER_KEYBOARD;
474	
475	    // Signal channel for guitar UI feedback (only used in guitar mode)
476	    let (signal_tx, signal_rx) = mpsc::channel::<crate::guitar_bridge::GuitarSignalInfo>();
477	
478	    if is_guitar {
479	        // Guitar Audio mode: spawn cpal capture -> DSP -> same tx channel
480	        let bridge = GuitarBridge::new(
481	            &guitar_device,
482	            guitar_channel,
483	            guitar_config,
484	            guitar_config_shared,
485	            calibration_profile,
486	            live_pipeline_handle,
487	            tx,
488	            Some(signal_tx),
489	        )
490	        .map_err(|e| anyhow::anyhow!("Guitar bridge error: {}", e))?;
491	        _guitar_bridge = Some(bridge);
492	        _midi_conn = None;
493	    } else if is_keyboard {
494	        // Computer Keyboard mode: no physical connection. The tx is kept
495	        // alive by the AppState clone so inject_note_on/off can push.
496	        // Drop the local tx copy; AppState keeps the channel open.
497	        drop(tx);
498	        _midi_conn = None;
499	        _guitar_bridge = None;
500	    } else {
501	        // Physical MIDI mode
502	        _midi_conn = Some(connect_input(input_port, tx)?);
503	        _guitar_bridge = None;
504	    };
505	
506	    // Create output router
507	    let mut output_router = OutputRouter::new(output_ports)?;
508	    let num_outputs = output_router.connection_count();
509	
510	    // voice_count is user-controlled via `set_voice_count`. With
511	    // per-voice routing, voices in excess of the connected MIDI ports
512	    // route to the built-in synth — there's no reason to clamp the
513	    // engine's voice_count to `num_outputs` at routing start. (Doing
514	    // so silently overrode the UI's voice picker — see the wave of
515	    // "I picked soprano in a 4-voice setup but the engine had only
516	    // 2 voices" reports.)
517	
518	    // Per-lane counters preserve overlapping voices at the same pitch.
519	    // They stay separate from generic harmony so Live Lines can render
520	    // each musical source without subtracting ambiguous pitch unions.
521	    let canon_notes: Arc<Mutex<NoteCounts>> = Arc::new(Mutex::new(HashMap::new()));
522	    let counterpoint_notes: Arc<Mutex<NoteCounts>> = Arc::new(Mutex::new(HashMap::new()));
523	    let mut companion_output_notes: RoutedNoteCounts = HashMap::new();
524	
525	    // Event emission timer (~30fps)
526	    let mut last_emit = Instant::now();
527	    let emit_interval = Duration::from_millis(33);
528	
529	    // Detune: track the previous value so we only send pitch bend on change.
530	    let mut prev_detune_cents: i32 = detune_cents.load(Ordering::Relaxed);
531	
532	    // Main routing loop
533	    loop {
534	        if stop_signal.load(Ordering::SeqCst) {
535	            break;
536	        }
537	
538	        // Push current beat-phase from the transport clock to the engine.
539	        // Counterpoint Species 2-4 read this on every NoteOn to decide
540	        // passing tones / suspensions / strong-vs-weak-beat behavior.
541	        // Without a fresh phase, the engine sees None and silently falls
542	        // back to Species 1 regardless of which Species the user picked.
543	        // When transport is stopped we explicitly push None so Species
544	        // 2-4 fall back to Species 1 (per the engine doc on
545	        // `counterpoint_beat_phase: Option<f64>`).
546	        {
547	            let phase = if transport.is_running() {
548	                Some(transport.beat_position())
549	            } else {
550	                None
551	            };
552	            let mut eng = engine.lock().unwrap_or_else(|e| e.into_inner());
553	            eng.set_counterpoint_beat_phase(phase);
554	        }
555	
556	        // #91 commit A: tick the Companion orchestrator. When
557	        // `enabled = false` (the default), tick() short-circuits and
558	        // returns an empty Vec — zero overhead per iteration. When
559	        // Lanes are registered and the master switch is on, the
560	        // returned ops are translated to dispatch_voice /
561	        // broadcast_note_off via dispatch_companion_ops.
562	        //
563	        // Held briefly across only this loop iteration so Tauri
564	        // command handlers (enable/disable, register Lane — future
565	        // commits) can acquire the lock between ticks.
566	        {
567	            let num_ports = output_router.connection_count();
568	            let tagged = {
569	                let mut c = companion.lock().unwrap_or_else(|e| e.into_inner());
570	                c.tick_tagged(&engine)
571	            };
572	            dispatch_companion_ops(
573	                &tagged,
574	                num_ports,
575	                &synth_tx,
576	                &mut output_router,
577	                &harmony_notes,
578	                &canon_notes,
579	                &counterpoint_notes,
580	                &mut companion_output_notes,
581	            );
582	        }
583	
584	        // Beat-aligned chord retrigger. When pattern is enabled and the
585	        // transport is running, detect cell-boundary crossings and
586	        // retrigger the currently-sounding harmony on each cell-on
587	        // boundary (Live mode). Skip silently when pattern off or
588	        // transport stopped — fall through to today's real-time path.
589	        //
590	        // Skip entirely when `panic_pending` is set: this iteration

