208	export function validateArrangementPreset(preset: ArrangementPresetV2): string[] {
209		const errors = validateArrangementConfig(preset.config);
210		if (
211			preset.researchStatus === 'approved' &&
212			preset.config.companion.canon.enabled &&
213			!preset.requirements.includes('phrase_capture') &&
214			preset.config.companion.canon.voices.some((voice) => voice.timeRatio < 1)
215		) {
216			errors.push('Live proportional ratios below 1 require phrase capture');
217		}
218		if (
219			preset.researchStatus === 'approved' &&
220			preset.config.companion.canon.form === 'strict_canon' &&
221			preset.config.companion.canon.voices.some(
222				(voice) =>
223					voice.timeRatio !== 1 || voice.harmonyMode !== 'PassThrough' || voice.voiceCount !== 1
224			)
225		) {
226			errors.push('Strict Canon followers must be single PassThrough lines at timeRatio 1');
227		}
228		return errors;
