231	export function validateArrangementConfig(config: ArrangementConfig): string[] {
232		const errors: string[] = [];
233		if (config.harmony.voiceCount < 1 || config.harmony.voiceCount > 8) {
234			errors.push('voiceCount must be between 1 and 8');
235		}
236		if (
237			config.harmony.voicePosition < 0 ||
238			config.harmony.voicePosition >= config.harmony.voiceCount
239		) {
240			errors.push('voicePosition must address an active voice');
241		}
242		if (config.harmony.mode === 'ExplicitIntervals') {
243			const map = config.harmony.explicitIntervalMap;
244			if (!map) {
245				errors.push('ExplicitIntervals mode requires explicitIntervalMap');
246			} else {
247				if (map.degreeOffsets.length !== 7) {
248					errors.push('explicitIntervalMap requires exactly seven degree entries');
249				}
250				for (const [label, offsets] of [
251					...map.degreeOffsets.map((offsets, index) => [`degree ${index + 1}`, offsets] as const),
252					['fallback', map.fallbackOffsets] as const
253				]) {
254					if (offsets.length > 7) errors.push(`${label} supports at most seven interval offsets`);
255					if (offsets.some((offset, index) => !Number.isInteger(offset) || offset === 0 || offset < -48 || offset > 48 || offsets.indexOf(offset) !== index)) {
256						errors.push(`${label} interval offsets must be unique nonzero integers between -48 and 48`);
257					}
258				}
259			}
260		}
261		if (config.companion.canon.voices.length > 8) {
262			errors.push('Canon supports at most 8 voices');
263		}
264		for (const [index, voice] of config.companion.canon.voices.entries()) {
265			if (!Number.isFinite(voice.timeRatio) || voice.timeRatio < 0.125 || voice.timeRatio > 8) {
266				errors.push(`Canon voice ${index + 1} timeRatio must be between 0.125 and 8`);
267			}
268		}
269		if (config.companion.patterns) {
270			for (const [role, pattern] of Object.entries(config.companion.patterns)) {
271				if (!Number.isFinite(pattern.cycleBeats) || pattern.cycleBeats < 0.25 || pattern.cycleBeats > 32) {
272					errors.push(`${role} cycleBeats must be between 0.25 and 32`);
273				}
274				if (!Number.isFinite(pattern.tailBeats) || pattern.tailBeats < 0.25 || pattern.tailBeats > 32) {
275					errors.push(`${role} tailBeats must be between 0.25 and 32`);
276				}
277				if (pattern.events.length > 16) errors.push(`${role} supports at most 16 events`);
278				for (const event of pattern.events) {
279					if (!Number.isFinite(event.beat) || event.beat < 0 || event.beat >= pattern.cycleBeats) {
280						errors.push(`${role} event beat must fall inside the cycle`);
281					}
282					if (!Number.isInteger(event.degree) || event.degree < 0 || event.degree > 6) {
283						errors.push(`${role} event degree must be between 0 and 6`);
284					}
285					if (!Number.isInteger(event.octave) || event.octave < -4 || event.octave > 4) {
286						errors.push(`${role} event octave must be between -4 and 4`);
287					}
288					if (!Number.isFinite(event.durationBeats) || event.durationBeats < 0.03125 || event.durationBeats > 32) {
289						errors.push(`${role} event durationBeats must be between 0.03125 and 32`);
290					}
291					if (!Number.isInteger(event.velocity) || event.velocity < 1 || event.velocity > 127) {
292						errors.push(`${role} event velocity must be between 1 and 127`);
293					}
294				}
295			}
296		}
297		for (const [role, value] of Object.entries(config.mix)) {
298			if (!Number.isFinite(value) || value < 0 || value > 1) {
299				errors.push(`${role} mix must be between 0 and 1`);
300			}
301		}
302		return errors;
303	}
