 10	export function loadUserArrangementPresets(): ArrangementPresetV2[] {
 11		if (typeof localStorage === 'undefined') return [];
 12		try {
 13			const saved = JSON.parse(localStorage.getItem(ARRANGEMENT_PRESET_STORAGE_KEY) ?? 'null');
 14			if (saved?.version === 2 && Array.isArray(saved.presets)) {
 15				return saved.presets.filter(isUserArrangementPreset);
 16			}
 17	
 18			const legacy = JSON.parse(localStorage.getItem(LEGACY_STORAGE_KEY) ?? '[]');
 19			if (!Array.isArray(legacy)) return [];
 20			const migrated = legacy.map(migrateLegacyPreset).filter((preset) => preset !== null);
 21			if (migrated.length) saveUserArrangementPresets(migrated);
 22			return migrated;
 23		} catch {
 24			return [];
 25		}
 26	}
 27	
 28	export function saveUserArrangementPresets(presets: ArrangementPresetV2[]) {
 29		if (typeof localStorage === 'undefined') return;
 30		localStorage.setItem(
 31			ARRANGEMENT_PRESET_STORAGE_KEY,
 32			JSON.stringify({ version: 2, presets: presets.filter((preset) => !preset.builtIn) })
 33		);
 34	}
 35	
 36	export function migrateLegacyPreset(value: unknown): ArrangementPresetV2 | null {
 37		if (!isRecord(value) || value.builtIn !== false) return null;
 38		if (typeof value.id !== 'string' || typeof value.name !== 'string') return null;
 39		if (
 40			typeof value.scaleMode !== 'string' ||
 41			typeof value.mode !== 'string' ||
 42			typeof value.voiceCount !== 'number' ||
 43			typeof value.voicePosition !== 'number' ||
 44			typeof value.voiceLeadingEnabled !== 'boolean' ||
 45			typeof value.voiceLeadingStyle !== 'string' ||
 46			typeof value.octaveMode !== 'string' ||
 47			typeof value.companionEnabled !== 'boolean' ||
 48			typeof value.canonEnabled !== 'boolean' ||
 49			(value.imitativeForm !== 'strict_canon' && value.imitativeForm !== 'free_imitation') ||
 50			!Array.isArray(value.canonVoices)
 51		) {
 52			return null;
 53		}
 54	
 55		const counterpoint = isRecord(value.counterpoint) ? value.counterpoint : null;
 56		const counterpointEnabled = counterpoint?.enabled === true;
 57		const requirements = new Set<ArrangementCapability>(['harmony']);
 58		if (value.voiceLeadingEnabled) requirements.add('voice_leading');
 59		if (value.canonEnabled) requirements.add(value.imitativeForm);
 60		if (counterpointEnabled) requirements.add('species_counterpoint');
 61	
 62		return {
 63			schemaVersion: 2,
 64			id: value.id,
 65			name: value.name,
 66			family: 'custom',
 67			tags: ['migrated'],
 68			builtIn: false,
 69			result: 'Migrated custom arrangement.',
 70			play: {
 71				prompt: 'Play naturally; edit this preset to add performance guidance.',
 72				input: 'single_notes',
 73				articulation: 'Any',
 74				density: 'Any',
 75				space: 'As needed',
 76				transportRequired: value.canonEnabled
 77			},
 78			references: [],
 79			researchStatus: 'not_required',
 80			requirements: [...requirements],
 81			config: {
 82				harmony: {
 83					scaleMode: value.scaleMode as ArrangementPresetV2['config']['harmony']['scaleMode'],
 84					mode: value.mode as ArrangementPresetV2['config']['harmony']['mode'],
 85					voiceCount: value.voiceCount,
 86					voicePosition: value.voicePosition,
 87					voiceLeadingEnabled: value.voiceLeadingEnabled,
 88					voiceLeadingStyle: value.voiceLeadingStyle as ArrangementPresetV2['config']['harmony']['voiceLeadingStyle'],
 89					octaveMode: value.octaveMode as ArrangementPresetV2['config']['harmony']['octaveMode'],
 90					octaveIntensity: 1,
 91					interchangeEnabled: false,
 92					interchangeRange: 3,
 93					counterpointSpecies: (typeof value.harmonySpecies === 'string' ? value.harmonySpecies : 'Species1') as ArrangementPresetV2['config']['harmony']['counterpointSpecies'],
 94					counterpointStrictness: 'Strict'
 95				},
 96				companion: {
 97					enabled: value.companionEnabled,
 98					globalHoldMode: { kind: 'near_future', tail_beats: 1 },
 99					canon: {
100						enabled: value.canonEnabled,
101						form: value.imitativeForm,
102						holdMode: null,
103						voices: value.canonVoices.map(migrateLegacyCanonVoice).filter((voice) => voice !== null)
104					},
105					counterpoint: {
106						enabled: counterpointEnabled,
107						species: (typeof counterpoint?.species === 'string' ? counterpoint.species : 'Species1') as ArrangementPresetV2['config']['companion']['counterpoint']['species'],
108						transposeDegrees: typeof counterpoint?.transpose_degrees === 'number' ? counterpoint.transpose_degrees : 2,
109						preferAbove: counterpoint?.prefer_above !== false,
110						holdMode: null
111					}
112				},
113				mix: { input: 1, harmony: 1, canon: 1, counterpoint: 1 }
114			}
115		};
116	}
117	
118	function migrateLegacyCanonVoice(value: unknown): ArrangementCanonVoiceConfig | null {
119		if (!isRecord(value)) return null;
120		if (typeof value.delay_beats !== 'number' || typeof value.transpose_degrees !== 'number') {
121			return null;
122		}
123		return {
124			delayBeats: value.delay_beats,
125			transposeDegrees: value.transpose_degrees,
126			timeRatio: typeof value.time_ratio === 'number' ? value.time_ratio : 1,
127			harmonyMode: typeof value.harmony_mode === 'string' ? value.harmony_mode as ArrangementCanonVoiceConfig['harmonyMode'] : null,
128			referenceVoice: typeof value.reference_voice === 'number' ? value.reference_voice : null,
129			voiceCount: typeof value.voice_count === 'number' ? value.voice_count : null,
130			voicePosition: typeof value.voice_position === 'number' ? value.voice_position : null,
131			voiceLeadingEnabled: typeof value.voice_leading_enabled === 'boolean' ? value.voice_leading_enabled : null,
132			voiceLeadingStyle: typeof value.voice_leading_style === 'string' ? value.voice_leading_style as ArrangementCanonVoiceConfig['voiceLeadingStyle'] : null,
133			octaveMode: typeof value.octave_mode === 'string' ? value.octave_mode as ArrangementCanonVoiceConfig['octaveMode'] : null,
134			counterpointSpecies: typeof value.counterpoint_species === 'string' ? value.counterpoint_species as ArrangementCanonVoiceConfig['counterpointSpecies'] : null,
135			counterpointStrictness: typeof value.counterpoint_strictness === 'string' ? value.counterpoint_strictness as ArrangementCanonVoiceConfig['counterpointStrictness'] : null,
136			holdMode: isRecord(value.hold_mode) ? value.hold_mode as ArrangementCanonVoiceConfig['holdMode'] : null
137		};
138	}
139	
140	function isUserArrangementPreset(value: unknown): value is ArrangementPresetV2 {
141		return isRecord(value)
142			&& value.schemaVersion === 2
143			&& value.builtIn === false
144			&& typeof value.id === 'string'
145			&& typeof value.name === 'string'
146			&& isRecord(value.config);
147	}
148	
149	function isRecord(value: unknown): value is Record<string, unknown> {
150		return typeof value === 'object' && value !== null;
151	}

