 72		voiceCount: number;
 73		voicePosition: number;
 74		voiceLeadingEnabled: boolean;
 75		voiceLeadingStyle: VoiceLeadingStyleName;
 76		octaveMode: OctaveModeName;
 77		octaveIntensity: number;
 78		interchangeEnabled: boolean;
 79		interchangeRange: number;
 80		counterpointSpecies: CounterpointSpeciesName;
 81		counterpointStrictness: CounterpointStrictnessName;
 82		/** Required when mode is ExplicitIntervals; optional for schema-v2 compatibility. */
 83		explicitIntervalMap?: ExplicitIntervalMapConfig;
 84	}
 85	
 86	export interface ArrangementCanonVoiceConfig {
 87		delayBeats: number;
 88		transposeDegrees: number;
 89		timeRatio: number;
 90		harmonyMode: HarmonyModeName | null;
 91		referenceVoice: number | null;
 92		voiceCount: number | null;
 93		voicePosition: number | null;
 94		voiceLeadingEnabled: boolean | null;
 95		voiceLeadingStyle: VoiceLeadingStyleName | null;
 96		octaveMode: OctaveModeName | null;
 97		counterpointSpecies: CounterpointSpeciesName | null;
 98		counterpointStrictness: CounterpointStrictnessName | null;
 99		holdMode: HoldMode | null;
100	}
101	
102	export interface ArrangementCanonConfig {
103		enabled: boolean;
104		form: ImitativeFormName;
105		holdMode: HoldMode | null;
106		voices: ArrangementCanonVoiceConfig[];
107	}
108	
109	export interface ArrangementCounterpointConfig {
110		enabled: boolean;
111		species: CounterpointSpeciesName;
112		transposeDegrees: number;
113		preferAbove: boolean;
114		holdMode: HoldMode | null;
115	}
116	
117	export type ArrangementPatternLaneId = 'pattern_low' | 'pattern_counter';
118	
119	export interface ArrangementPatternEventConfig {
120		beat: number;
121		degree: number;
122		octave: number;
123		durationBeats: number;
124		velocity: number;
125	}
126	
127	export interface ArrangementPatternLaneConfig {
128		enabled: boolean;
129		cycleBeats: number;
130		tailBeats: number;
131		events: ArrangementPatternEventConfig[];
132	}
133	
134	export interface ArrangementPatternConfig {
135		lowSupport: ArrangementPatternLaneConfig;
136		counterline: ArrangementPatternLaneConfig;
137	}
138	
139	export interface ArrangementConfig {
140		harmony: ArrangementHarmonyConfig;
141		companion: {
142			enabled: boolean;
143			globalHoldMode: HoldMode;
144			canon: ArrangementCanonConfig;
145			counterpoint: ArrangementCounterpointConfig;
146			/** Optional for backward-compatible schema-v2 user presets. */
147			patterns?: ArrangementPatternConfig;
148		};
149		mix: {
150			input: number;
151			harmony: number;
152			canon: number;
153			counterpoint: number;
154		};
155	}
156	
157	/**
158	 * Musical arrangement only. The absence of tonic, tempo, devices,
159	 * routing, sound, master level, mute/solo, plugins, and transport state
160	 * is intentional: applying a preset must preserve the performance
161	 * environment.
162	 */
163	export interface ArrangementPresetV2 {
164		schemaVersion: typeof ARRANGEMENT_PRESET_SCHEMA_VERSION;
165		id: string;
166		name: string;
167		family: ArrangementFamily;
168		tags: string[];
169		builtIn: boolean;
170		result: string;
171		approximation?: string;
172		play: PresetPlayGuide;
173		references: PresetReference[];
174		researchStatus: PresetResearchStatus;
175		requirements: ArrangementCapability[];
176		suggestedSoundPresetId?: string;
177		config: ArrangementConfig;
178	}
179	
180	export function missingArrangementCapabilities(
181		preset: Pick<ArrangementPresetV2, 'requirements'>,
182		available: ReadonlySet<ArrangementCapability>
183	): ArrangementCapability[] {
184		return preset.requirements.filter((capability) => !available.has(capability));
185	}
186	
187	export function arrangementConfigCapabilities(config: ArrangementConfig): ArrangementCapability[] {
188		const capabilities = new Set<ArrangementCapability>(['harmony']);
189		if (config.harmony.voiceLeadingEnabled) capabilities.add('voice_leading');
190		if (config.harmony.mode === 'ExplicitIntervals') capabilities.add('interval_stacks');
191		if (config.companion.enabled && config.companion.canon.enabled) {
192			capabilities.add(config.companion.canon.form);
193		}
194		if (config.companion.enabled && config.companion.counterpoint.enabled) {
195			capabilities.add('species_counterpoint');
196		}
197		const patterns = config.companion.patterns;
198		if (config.companion.enabled && patterns && (patterns.lowSupport.enabled || patterns.counterline.enabled)) {
199			capabilities.add('pattern_lane');
200			if (patterns.lowSupport.enabled && patterns.counterline.enabled) {
201				capabilities.add('stable_lane_groups');
202			}
203		}
204		if (Object.values(config.mix).some((value) => value !== 1)) capabilities.add('role_mix');
205		return [...capabilities];
206	}
207	
208	export function validateArrangementPreset(preset: ArrangementPresetV2): string[] {
209		const errors = validateArrangementConfig(preset.config);
210		if (
211			preset.researchStatus === 'approved' &&
212			preset.config.companion.canon.enabled &&
213			!preset.requirements.includes('phrase_capture') &&
214			preset.config.companion.canon.voices.some((voice) => voice.timeRatio < 1)
215		) {
216			errors.push('Live proportional ratios below 1 require phrase capture');
217		}
218		if (
219			preset.researchStatus === 'approved' &&
220			preset.config.companion.canon.form === 'strict_canon' &&
221			preset.config.companion.canon.voices.some(
222				(voice) =>
223					voice.timeRatio !== 1 || voice.harmonyMode !== 'PassThrough' || voice.voiceCount !== 1
224			)
225		) {
226			errors.push('Strict Canon followers must be single PassThrough lines at timeRatio 1');
227		}
228		return errors;
229	}
230	
231	export function validateArrangementConfig(config: ArrangementConfig): string[] {
232		const errors: string[] = [];
233		if (config.harmony.voiceCount < 1 || config.harmony.voiceCount > 8) {
234			errors.push('voiceCount must be between 1 and 8');
235		}
236		if (
237			config.harmony.voicePosition < 0 ||
238			config.harmony.voicePosition >= config.harmony.voiceCount
239		) {
240			errors.push('voicePosition must address an active voice');
241		}
242		if (config.harmony.mode === 'ExplicitIntervals') {
243			const map = config.harmony.explicitIntervalMap;
244			if (!map) {
245				errors.push('ExplicitIntervals mode requires explicitIntervalMap');
246			} else {
247				if (map.degreeOffsets.length !== 7) {
248					errors.push('explicitIntervalMap requires exactly seven degree entries');
249				}
250				for (const [label, offsets] of [
251					...map.degreeOffsets.map((offsets, index) => [`degree ${index + 1}`, offsets] as const),
252					['fallback', map.fallbackOffsets] as const
253				]) {
254					if (offsets.length > 7) errors.push(`${label} supports at most seven interval offsets`);
255					if (offsets.some((offset, index) => !Number.isInteger(offset) || offset === 0 || offset < -48 || offset > 48 || offsets.indexOf(offset) !== index)) {
256						errors.push(`${label} interval offsets must be unique nonzero integers between -48 and 48`);
257					}
258				}
259			}
260		}
261		if (config.companion.canon.voices.length > 8) {
262			errors.push('Canon supports at most 8 voices');
263		}
264		for (const [index, voice] of config.companion.canon.voices.entries()) {
265			if (!Number.isFinite(voice.timeRatio) || voice.timeRatio < 0.125 || voice.timeRatio > 8) {
266				errors.push(`Canon voice ${index + 1} timeRatio must be between 0.125 and 8`);
267			}
268		}
269		if (config.companion.patterns) {
270			for (const [role, pattern] of Object.entries(config.companion.patterns)) {
271				if (!Number.isFinite(pattern.cycleBeats) || pattern.cycleBeats < 0.25 || pattern.cycleBeats > 32) {
272					errors.push(`${role} cycleBeats must be between 0.25 and 32`);
273				}
274				if (!Number.isFinite(pattern.tailBeats) || pattern.tailBeats < 0.25 || pattern.tailBeats > 32) {
275					errors.push(`${role} tailBeats must be between 0.25 and 32`);
276				}
277				if (pattern.events.length > 16) errors.push(`${role} supports at most 16 events`);
278				for (const event of pattern.events) {
279					if (!Number.isFinite(event.beat) || event.beat < 0 || event.beat >= pattern.cycleBeats) {
280						errors.push(`${role} event beat must fall inside the cycle`);
281					}
282					if (!Number.isInteger(event.degree) || event.degree < 0 || event.degree > 6) {
283						errors.push(`${role} event degree must be between 0 and 6`);
284					}
285					if (!Number.isInteger(event.octave) || event.octave < -4 || event.octave > 4) {
286						errors.push(`${role} event octave must be between -4 and 4`);
287					}
288					if (!Number.isFinite(event.durationBeats) || event.durationBeats < 0.03125 || event.durationBeats > 32) {
289						errors.push(`${role} event durationBeats must be between 0.03125 and 32`);
290					}
291					if (!Number.isInteger(event.velocity) || event.velocity < 1 || event.velocity > 127) {
292						errors.push(`${role} event velocity must be between 1 and 127`);
293					}
294				}
295			}
296		}
297		for (const [role, value] of Object.entries(config.mix)) {
298			if (!Number.isFinite(value) || value < 0 || value > 1) {
299				errors.push(`${role} mix must be between 0 and 1`);
300			}
301		}
302		return errors;
303	}
  1	import type {
  2		ArrangementCapability,
  3		ArrangementPresetV2,
  4		ArrangementCanonVoiceConfig
  5	} from './presets';
  6	
  7	export const ARRANGEMENT_PRESET_STORAGE_KEY = 'contrapunk-arrangement-presets-v2';
  8	const LEGACY_STORAGE_KEY = 'contrapunk-ensemble-presets-v1';
  9	
 10	export function loadUserArrangementPresets(): ArrangementPresetV2[] {
 11		if (typeof localStorage === 'undefined') return [];
 12		try {
 13			const saved = JSON.parse(localStorage.getItem(ARRANGEMENT_PRESET_STORAGE_KEY) ?? 'null');
 14			if (saved?.version === 2 && Array.isArray(saved.presets)) {
 15				return saved.presets.filter(isUserArrangementPreset);
 16			}
 17	
 18			const legacy = JSON.parse(localStorage.getItem(LEGACY_STORAGE_KEY) ?? '[]');
 19			if (!Array.isArray(legacy)) return [];
 20			const migrated = legacy.map(migrateLegacyPreset).filter((preset) => preset !== null);
 21			if (migrated.length) saveUserArrangementPresets(migrated);
 22			return migrated;
 23		} catch {
 24			return [];
 25		}
 26	}
 27	
 28	export function saveUserArrangementPresets(presets: ArrangementPresetV2[]) {
 29		if (typeof localStorage === 'undefined') return;
 30		localStorage.setItem(
 31			ARRANGEMENT_PRESET_STORAGE_KEY,
 32			JSON.stringify({ version: 2, presets: presets.filter((preset) => !preset.builtIn) })
 33		);
 34	}
 35	
 36	export function migrateLegacyPreset(value: unknown): ArrangementPresetV2 | null {
 37		if (!isRecord(value) || value.builtIn !== false) return null;
 38		if (typeof value.id !== 'string' || typeof value.name !== 'string') return null;
 39		if (
 40			typeof value.scaleMode !== 'string' ||
 41			typeof value.mode !== 'string' ||
 42			typeof value.voiceCount !== 'number' ||
 43			typeof value.voicePosition !== 'number' ||
 44			typeof value.voiceLeadingEnabled !== 'boolean' ||
 45			typeof value.voiceLeadingStyle !== 'string' ||
 46			typeof value.octaveMode !== 'string' ||
 47			typeof value.companionEnabled !== 'boolean' ||
 48			typeof value.canonEnabled !== 'boolean' ||
 49			(value.imitativeForm !== 'strict_canon' && value.imitativeForm !== 'free_imitation') ||
 50			!Array.isArray(value.canonVoices)
 51		) {
 52			return null;
 53		}
 54	
 55		const counterpoint = isRecord(value.counterpoint) ? value.counterpoint : null;
 56		const counterpointEnabled = counterpoint?.enabled === true;
 57		const requirements = new Set<ArrangementCapability>(['harmony']);
 58		if (value.voiceLeadingEnabled) requirements.add('voice_leading');
 59		if (value.canonEnabled) requirements.add(value.imitativeForm);
 60		if (counterpointEnabled) requirements.add('species_counterpoint');
 61	
 62		return {
 63			schemaVersion: 2,
 64			id: value.id,
 65			name: value.name,
 66			family: 'custom',
 67			tags: ['migrated'],
 68			builtIn: false,
 69			result: 'Migrated custom arrangement.',
 70			play: {
 71				prompt: 'Play naturally; edit this preset to add performance guidance.',
 72				input: 'single_notes',
 73				articulation: 'Any',
 74				density: 'Any',
 75				space: 'As needed',
 76				transportRequired: value.canonEnabled
 77			},
 78			references: [],
 79			researchStatus: 'not_required',
 80			requirements: [...requirements],
 81			config: {
 82				harmony: {
 83					scaleMode: value.scaleMode as ArrangementPresetV2['config']['harmony']['scaleMode'],
 84					mode: value.mode as ArrangementPresetV2['config']['harmony']['mode'],
 85					voiceCount: value.voiceCount,
 86					voicePosition: value.voicePosition,
 87					voiceLeadingEnabled: value.voiceLeadingEnabled,
 88					voiceLeadingStyle: value.voiceLeadingStyle as ArrangementPresetV2['config']['harmony']['voiceLeadingStyle'],
 89					octaveMode: value.octaveMode as ArrangementPresetV2['config']['harmony']['octaveMode'],
 90					octaveIntensity: 1,
 91					interchangeEnabled: false,
 92					interchangeRange: 3,
 93					counterpointSpecies: (typeof value.harmonySpecies === 'string' ? value.harmonySpecies : 'Species1') as ArrangementPresetV2['config']['harmony']['counterpointSpecies'],
 94					counterpointStrictness: 'Strict'
 95				},
 96				companion: {
 97					enabled: value.companionEnabled,
 98					globalHoldMode: { kind: 'near_future', tail_beats: 1 },
 99					canon: {
100						enabled: value.canonEnabled,
101						form: value.imitativeForm,
102						holdMode: null,
103						voices: value.canonVoices.map(migrateLegacyCanonVoice).filter((voice) => voice !== null)
104					},
105					counterpoint: {
106						enabled: counterpointEnabled,
107						species: (typeof counterpoint?.species === 'string' ? counterpoint.species : 'Species1') as ArrangementPresetV2['config']['companion']['counterpoint']['species'],
108						transposeDegrees: typeof counterpoint?.transpose_degrees === 'number' ? counterpoint.transpose_degrees : 2,
109						preferAbove: counterpoint?.prefer_above !== false,
110						holdMode: null
111					}
112				},
113				mix: { input: 1, harmony: 1, canon: 1, counterpoint: 1 }
114			}
115		};
116	}
117	
118	function migrateLegacyCanonVoice(value: unknown): ArrangementCanonVoiceConfig | null {
119		if (!isRecord(value)) return null;
120		if (typeof value.delay_beats !== 'number' || typeof value.transpose_degrees !== 'number') {
121			return null;
122		}
123		return {
124			delayBeats: value.delay_beats,
125			transposeDegrees: value.transpose_degrees,
126			timeRatio: typeof value.time_ratio === 'number' ? value.time_ratio : 1,
127			harmonyMode: typeof value.harmony_mode === 'string' ? value.harmony_mode as ArrangementCanonVoiceConfig['harmonyMode'] : null,
128			referenceVoice: typeof value.reference_voice === 'number' ? value.reference_voice : null,
129			voiceCount: typeof value.voice_count === 'number' ? value.voice_count : null,
130			voicePosition: typeof value.voice_position === 'number' ? value.voice_position : null,
131			voiceLeadingEnabled: typeof value.voice_leading_enabled === 'boolean' ? value.voice_leading_enabled : null,
132			voiceLeadingStyle: typeof value.voice_leading_style === 'string' ? value.voice_leading_style as ArrangementCanonVoiceConfig['voiceLeadingStyle'] : null,
133			octaveMode: typeof value.octave_mode === 'string' ? value.octave_mode as ArrangementCanonVoiceConfig['octaveMode'] : null,
134			counterpointSpecies: typeof value.counterpoint_species === 'string' ? value.counterpoint_species as ArrangementCanonVoiceConfig['counterpointSpecies'] : null,
135			counterpointStrictness: typeof value.counterpoint_strictness === 'string' ? value.counterpoint_strictness as ArrangementCanonVoiceConfig['counterpointStrictness'] : null,
136			holdMode: isRecord(value.hold_mode) ? value.hold_mode as ArrangementCanonVoiceConfig['holdMode'] : null
137		};
138	}
139	
140	function isUserArrangementPreset(value: unknown): value is ArrangementPresetV2 {
141		return isRecord(value)
142			&& value.schemaVersion === 2
143			&& value.builtIn === false
144			&& typeof value.id === 'string'
145			&& typeof value.name === 'string'
146			&& isRecord(value.config);
147	}
148	
149	function isRecord(value: unknown): value is Record<string, unknown> {
150		return typeof value === 'object' && value !== null;
151	}

