  1	<script lang="ts">
  2		import { onMount } from 'svelte';
  3		import PixelSelect from './PixelSelect.svelte';
  4		import {
  5			arrangementConfigCapabilities,
  6			missingArrangementCapabilities,
  7			validateArrangementPreset,
  8			type ArrangementPresetV2
  9		} from '$lib/arrangement/presets';
 10		import { arrangement } from '$lib/stores/arrangement.svelte';
 11		import { arrangementPresets } from '$lib/stores/arrangementPresets.svelte';
 12	
 13		let { compact = false }: { compact?: boolean } = $props();
 14		let applying = $state(false);
 15		let saveOpen = $state(false);
 16		let saveName = $state('');
 17		let saveResult = $state('');
 18		let savePrompt = $state('');
 19		let saveReferences = $state('');
 20		let error = $state('');
 21	
 22		let presets = $derived(arrangementPresets.allPresets);
 23		let selected = $derived(presets.find((preset) => preset.id === arrangementPresets.selectedId));
 24		let missing = $derived(
 25			selected
 26				? missingArrangementCapabilities(selected, arrangement.availableCapabilities)
 27				: []
 28		);
 29		let researchLocked = $derived(
 30			selected?.builtIn === true && selected.researchStatus !== 'approved'
 31		);
 32		let presetErrors = $derived(selected ? validateArrangementPreset(selected) : []);
 33		let canApply = $derived(
 34			!!selected && !researchLocked && missing.length === 0 && presetErrors.length === 0 && !applying
 35		);
 36		let options = $derived(
 37			presets.map((preset) => ({
 38				value: preset.id,
 39				label: `${preset.builtIn ? (preset.researchStatus === 'approved' ? '' : '◇ ') : '★ '}${preset.name}`
 40			}))
 41		);
 42		let availability = $derived(
 43			researchLocked
 44				? 'Research pending — Apply stays locked.'
 45				: missing.length
 46					? `Unavailable here — missing ${missing.join(', ')}.`
 47					: presetErrors.length
 48						? `Invalid preset — ${presetErrors.join('; ')}.`
 49						: 'Available on this surface.'
 50		);
 51	
 52		onMount(() => {
 53			void arrangement.syncFromBackend();
 54		});
 55	
 56		async function applySelected() {
 57			if (!selected || !canApply) return;
 58			applying = true;
 59			error = '';
 60			try {
 61				await arrangement.apply(selected.config);
 62				arrangementPresets.appliedId = selected.id;
 63			} catch (cause) {
 64				error = `Apply failed: ${cause}`;
 65			} finally {
 66				applying = false;
 67			}
 68		}
 69	
 70		function openSaveAs() {
 71			const source = selected && (!selected.builtIn || selected.researchStatus === 'approved')
 72				? selected
 73				: undefined;
 74			saveName = source ? `${source.name} Copy` : 'Custom Arrangement';
 75			saveResult = source?.result ?? 'A custom arrangement captured from the current controls.';
 76			savePrompt = source?.play.prompt ?? 'Play naturally and leave space to hear the arrangement.';
 77			saveReferences = source?.references.map((reference) => reference.name).join(', ') ?? '';
 78			saveOpen = true;
 79		}
 80	
 81		function saveCurrent() {
 82			const name = saveName.trim();
 83			const result = saveResult.trim();
 84			const prompt = savePrompt.trim();
 85			if (!name || !result || !prompt) return;
 86	
 87			const source = selected && (!selected.builtIn || selected.researchStatus === 'approved')
 88				? selected
 89				: undefined;
 90			const config = arrangement.snapshot();
 91			const id = arrangementPresets.create({
 92				name,
 93				family: 'custom',
 94				tags: source ? [...source.tags, 'custom'] : ['custom'],
 95				result,
 96				approximation: source?.approximation,
 97				play: {
 98					...(source?.play ?? defaultPlayGuide()),
 99					prompt
100				},
101				references: saveReferences
102					.split(',')
103					.map((name) => name.trim())
104					.filter(Boolean)
105					.map((name) => ({ name, context: 'User-authored reference.' })),
106				researchStatus: 'not_required',
107				requirements: arrangementConfigCapabilities(config),
108				suggestedSoundPresetId: source?.suggestedSoundPresetId,
109				config
110			});
111			arrangementPresets.selectedId = id;
112			arrangementPresets.appliedId = id;
113			saveOpen = false;
114			error = '';
115		}
116	
117		function defaultPlayGuide(): ArrangementPresetV2['play'] {
118			return {
119				prompt: '',
120				input: 'single_notes',
121				articulation: 'As configured.',
122				density: 'As configured.',
123				space: 'Leave room for generated parts.',
124				transportRequired: false
125			};
126		}
127	</script>
128	
129	<section
130		class="preset-bar"
131		class:compact
132		aria-label="Arrangement preset"
133		title={compact && selected ? `${availability}\nResult: ${selected.result}\nPlay it like: ${selected.play.prompt}` : undefined}
134	>
135		<div class="toolbar">
136			<div class="preset-label font-ui">{compact ? 'PRESET' : 'ARRANGEMENT'}</div>
137			<PixelSelect
138				options={options}
139				value={arrangementPresets.selectedId}
140				label="Arrangement preset"
