     1	<!--
     2		PerformanceView — simplified 8-knob layout for non-experts and live use.
     3	
     4		Spec lives in .planning/PERFORMANCE-VIEW.md. Eight knobs:
     5		  Mode  Voices  Tightness  Adventurous
     6		  Key   Scale   Your register   Spread
     7	
     8		Composite knobs (Tightness / Adventurous / Spread) hold local state and
     9		fan out to multiple engine setters on change. They do NOT round-trip
    10		from engine state — they just display the user's last-touched position
    11		(per .planning/PERFORMANCE-VIEW.md, "Implementation notes").
    12	-->
    13	
    14	<script lang="ts">
    15		import { onMount, onDestroy } from 'svelte';
    16		import { engine, ALL_KEYS, KEY_DISPLAY } from '$lib/stores/engine.svelte';
    17		import type {
    18			HarmonyModeName,
    19			ScaleModeName,
    20			VoiceLeadingStyleName,
    21			KeyName
    22		} from '$lib/stores/engine.svelte';
    23		import { adapter } from '$lib/adapter';
    24		import { knobMidiMap, type KnobIndex } from '$lib/stores/knobMidiMap.svelte';
    25		import Knob from './Knob.svelte';
    26	
    27		let { midiLearnEnabled = true }: { midiLearnEnabled?: boolean } = $props();
    28	
    29		// === Mode (5 detents) ===
    30		const MODE_LABELS = [
    31			'Off',
    32			'Parallel 3rds',
    33			'Parallel 4ths',
    34			'Contrary',
    35			'Functional',
    36			...(adapter.capabilities.intervalMaps ? ['Interval Map'] : [])
    37		];
    38		const MODE_TO_ENGINE: HarmonyModeName[] = [
    39			'PassThrough',
    40			'DiatonicThirds',
    41			'DiatonicFourths',
    42			'ContraryMotion',
    43			'FunctionalHarmony',
    44			...(adapter.capabilities.intervalMaps ? (['ExplicitIntervals'] as HarmonyModeName[]) : [])
    45		];
    46		function engineModeToIndex(m: HarmonyModeName): number {
    47			const i = MODE_TO_ENGINE.indexOf(m);
    48			return i >= 0 ? i : 0;
    49		}
    50		let modeIndex = $derived(engineModeToIndex(engine.mode));
    51		function onModeChange(v: number) {
    52			const i = Math.round(v);
    53			void engine.setMode(MODE_TO_ENGINE[i]);
    54		}
    55	
    56		// === Scale (8 categories, representative sub-mode each) ===
    57		const SCALE_CATEGORIES: { label: string; engine: ScaleModeName }[] = [
    58			{ label: 'Pentatonic', engine: 'MajorPentatonic' },
    59			{ label: 'Major', engine: 'Ionian' },
    60			{ label: 'Natural Minor', engine: 'Aeolian' },
    61			{ label: 'Harmonic Min', engine: 'HarmonicMinor' },
    62			{ label: 'Melodic Min', engine: 'MelodicMinor' },
    63			{ label: 'Modal', engine: 'Dorian' },
    64			{ label: 'World', engine: 'Pelog' },
    65			{ label: 'Symmetric', engine: 'WholeTone' }
    66		];
    67		function engineScaleToCategoryIndex(s: ScaleModeName): number {
    68			// Map any sub-mode back to its category index for first-paint.
    69			const cats: Record<string, number> = {
    70				MajorPentatonic: 0, MinorPentatonic: 0, Hirajoshi: 0, InSen: 0, Iwato: 0, Yo: 0, Kumoi: 0,
    71				Ionian: 1,
    72				Aeolian: 2,
    73				HarmonicMinor: 3, LocrianNat6: 3, IonianAug: 3, DorianSharp4: 3,
    74				PhrygianDominant: 3, LydianSharp2: 3, SuperLocrianDim: 3,
    75				MelodicMinor: 4, DorianFlat2: 4, LydianAug: 4, LydianDominant: 4,
    76				MixolydianFlat6: 4, LocrianNat2: 4, SuperLocrian: 4,
    77				Dorian: 5, Phrygian: 5, Lydian: 5, Mixolydian: 5, Locrian: 5,
    78				Pelog: 6, Persian: 6, NeapolitanMajor: 6, NeapolitanMinor: 6,
    79				Enigmatic: 6, HungarianMajor: 6, HungarianMinor: 6, Oriental: 6,
    80				WholeTone: 7, DiminishedWholeHalf: 7, DiminishedHalfWhole: 7, AugmentedHex: 7
    81			};
    82			return cats[s] ?? 1;
    83		}
    84		let scaleIndex = $derived(engineScaleToCategoryIndex(engine.scaleMode));
    85		function onScaleChange(v: number) {
    86			const i = Math.round(v);
    87			void engine.setScaleMode(SCALE_CATEGORIES[i].engine);
    88		}
    89	
    90		// === Key (12 detents) + Auto-key toggle ===
    91		function engineKeyToIndex(k: KeyName): number {
    92			const i = ALL_KEYS.indexOf(k);
    93			return i >= 0 ? i : 0;
    94		}
    95		let keyIndex = $derived(engineKeyToIndex(engine.key));
    96		function onKeyChange(v: number) {
    97			const i = Math.round(v);
    98			// Touching the Key knob disables Auto-key with a visible state change.
    99			// Per the brutal-critic UI review fix (.planning/PERFORMANCE-VIEW.md).
   100			if (engine.autoKey) {
   101				void engine.setAutoKey(false);
   102			}
   103			void engine.setKey(ALL_KEYS[i]);
   104		}
   105	
   106		// === Voices (1-8) ===
   107		function onVoicesChange(v: number) {
   108			void engine.setVoiceCount(Math.round(v));
   109		}
   110	
   111		// === Your register (1..voiceCount) ===
   112		function onRegisterChange(v: number) {
   113			void engine.setVoicePosition(Math.round(v) - 1);
   114		}
   115	
   116		// === Tightness (0..1, composite) ===
   117		let tightness = $state(0.5);
   118		function tightnessLabel(t: number): string {
   119			if (t < 0.3) return 'Off';
   120			if (t < 0.6) return 'Loose';
   121			if (t < 0.85) return 'Smooth';
   122			return 'Strict';
   123		}
   124		function applyTightness(t: number) {
   125			tightness = t;
   126			if (t < 0.3) {
   127				void engine.setVoiceLeading(false);
   128				return;
   129			}
   130			const style: VoiceLeadingStyleName =
   131				t < 0.6 ? 'Free' : t < 0.85 ? 'Jazz' : 'Palestrina';
   132			void engine.setVoiceLeading(true, style);
   133		}
   134	
   135		// === Adventurous (0..1, composite) ===
   136		let adventurous = $state(0);
   137		function adventurousLabel(a: number): string {
   138			if (a <= 0.05) return 'In-key';
   139			const range = Math.max(1, Math.min(7, Math.round(a * 7)));
   140			return `Borrow ${range}`;
   141		}
   142		function applyAdventurous(a: number) {
   143			adventurous = a;
   144			if (a <= 0) {
   145				void engine.setInterchange(false, 1);
   146				return;
   147			}
   148			const range = Math.max(1, Math.min(7, Math.round(a * 7)));
   149			void engine.setInterchange(true, range);
   150		}
   151	
   152		// === Spread (continuous via engine octave_intensity coefficient) ===
   153		// Engine takes a continuous f32 intensity that scales per-voice
   154		// octave displacement. 0 = no spread (matches OctaveMode::None);
   155		// 1 = full-octave spread (matches legacy OctaveMode::Spread).
   156		// Mirror / BassTrebleSplit aren't exposed in this knob — they
   157		// remain available in the Advanced view's full Octave Mode picker.
   158		let spread = $state(0);
   159		function spreadLabel(s: number): string {
   160			if (s <= 0.01) return 'Tight';
   161			return `Wide ${Math.round(s * 100)}%`;
   162		}
   163		function applySpread(s: number) {
   164			spread = s;
   165			if (s <= 0.01) {
   166				void engine.setOctaveMode('None');
   167			} else {
   168				// Set mode first so apply_octave_mode hits the Spread branch,
   169				// then push the intensity coefficient.
   170				void engine.setOctaveMode('Spread');
   171				void engine.setOctaveIntensity(s);
   172			}
   173		}
   174	
   175		// Auto-key handling
   176		function toggleAutoKey() {
   177			void engine.setAutoKey(!engine.autoKey);
   178		}
   179	
   180		// === Hardware-knob CC routing (MIDI Learn) ===
   181		// Backend emits "knob-cc-raw" events with `{ cc, value }` for every
   182		// MIDI CC received. We resolve the CC → knob-index via the user's
   183		// learned mapping (`knobMidiMap`), then dispatch to the same apply
   184		// function the on-screen knob uses. While a knob is in "learning"
   185		// state, the next CC observed binds to that knob instead.
   186		function dispatchKnobValue(idx: KnobIndex, value: number) {
   187			switch (idx) {
   188				case 0: // Mode (5 detents)
   189					onModeChange(value * 4);
   190					break;
   191				case 1: // Voices (1-8)
   192					onVoicesChange(1 + value * 7);
   193					break;
   194				case 2: // Tightness (0..1)
   195					applyTightness(value);
   196					break;
   197				case 3: // Adventurous (0..1)
   198					applyAdventurous(value);
   199					break;
   200				case 4: // Key (12 detents) — also disables auto-key on hardware turn
   201					onKeyChange(value * 11);
   202					break;
   203				case 5: // Scale (8 categories)
   204					onScaleChange(value * 7);
   205					break;
   206				case 6: // Your register (1..voiceCount)
   207					onRegisterChange(1 + value * Math.max(0, engine.voiceCount - 1));
   208					break;
   209				case 7: // Spread (continuous)
   210					applySpread(value);
   211					break;
   212			}
   213		}
   214	
   215		let unlistenKnobCc: (() => void) | undefined;
   216		onMount(() => {
   217			unlistenKnobCc = adapter.onKnobCcRaw((cc, value) => {
   218				if (!midiLearnEnabled) return;
   219				const learning = knobMidiMap.learning;
   220				if (learning !== null) {
   221					// Capture this CC as the bound CC for the learning knob.
   222					knobMidiMap.bind(learning, cc);
   223					knobMidiMap.cancelLearn();
   224					return;
   225				}
   226				const idx = knobMidiMap.knobForCc(cc);
   227				if (idx !== null) dispatchKnobValue(idx, value);
   228			});
   229	
   230			// Escape cancels in-progress learning.
   231			const onKey = (e: KeyboardEvent) => {
   232				if (e.key === 'Escape' && knobMidiMap.learning !== null) {
   233					knobMidiMap.cancelLearn();
   234				}
   235			};
   236			window.addEventListener('keydown', onKey);
   237			return () => window.removeEventListener('keydown', onKey);
   238		});
   239		onDestroy(() => {
   240			unlistenKnobCc?.();
   241		});
   242	
   243		function toggleLearn(idx: KnobIndex) {
   244			knobMidiMap.toggleLearn(idx);
   245		}
   246	
   247		function ccLabel(idx: KnobIndex): string {
   248			const cc = knobMidiMap.map[idx];
   249			return cc === null ? '—' : `CC${cc}`;
   250		}
   251	
   252		function resetMidiMap() {
   253			knobMidiMap.resetToMpkDefaults();
   254		}
   255	</script>
   256	
   257	{#snippet learnPip(idx: KnobIndex)}
   258		<button
   259			type="button"
   260			class="learn-pip font-ui"
