623:                let inputs = eng.take_reharm_inputs();
667:                // take_reharm_inputs); same as the to_release loop
1303:/// `take_pending_releases` / `take_reharm_inputs`. Tracked as a
   585	        // transport is running, detect cell-boundary crossings and
   586	        // retrigger the currently-sounding harmony on each cell-on
   587	        // boundary (Live mode). Skip silently when pattern off or
   588	        // transport stopped — fall through to today's real-time path.
   589	        //
   590	        // Skip entirely when `panic_pending` is set: this iteration
   591	        // belongs to the reharmonize cycle below, which will replay
   592	        // held inputs and dispatch a clean diff. Firing the pattern
   593	        // tick first would attack stale `harmony_notes` and produce an
   594	        // audible click as reharm immediately releases the displaced
   595	        // voices.
   596	        let panic_will_fire = panic_pending.load(Ordering::SeqCst);
   597	
   598	        // Reharmonize on parameter change. Any engine-config setter that
   599	        // could change the harmony output sets panic_pending and stashes
   600	        // the previously-held input MIDI numbers in the engine's
   601	        // `pending_reharm_inputs`. We replay each of those inputs under
   602	        // the new parameters, compute a diff against the previously-
   603	        // sounding harmony set, and dispatch only the difference:
   604	        // NoteOff for harmony notes that drop out, NoteOn for newly-
   605	        // needed ones. The user's held input note never gets
   606	        // interrupted — knob sweeps produce a smooth musical morph.
   607	        if panic_pending.swap(false, Ordering::SeqCst) {
   608	            // Snapshot what's currently sounding (harmony + borrowed only —
   609	            // input notes belong to the user, leave them alone).
   610	            let old_harmonies: HashSet<u8> = {
   611	                let h = harmony_notes.lock().unwrap_or_else(|e| e.into_inner());
   612	                let b = borrowed_notes.lock().unwrap_or_else(|e| e.into_inner());
   613	                h.iter().chain(b.iter()).copied().collect()
   614	            };
   615	
   616	            // Drain held inputs from the engine and replay them under the
   617	            // new parameters. Each replay populates `active_notes` and
   618	            // updates `last_port_map` for the per-voice routing below.
   619	            let mut new_harmonies: HashSet<u8> = HashSet::new();
   620	            let mut per_input: Vec<(Vec<u8>, Vec<usize>)> = Vec::new();
   621	            {
   622	                let mut eng = engine.lock().unwrap_or_else(|e| e.into_inner());
   623	                let inputs = eng.take_reharm_inputs();
   624	                for midi in inputs {
   625	                    if let Ok(input_note) = Note::try_from(midi) {
   626	                        let result = eng.harmonize_note_on(input_note);
   627	                        let port_map = eng.last_port_map().to_vec();
   628	                        // Skip index 0 (the input itself) — only harmonies
   629	                        // contribute to the diff. Input keeps ringing.
   630	                        let harm_midis: Vec<u8> =
   631	                            result.iter().skip(1).map(|n| u8::from(*n)).collect();
   632	                        for &m in &harm_midis {
   633	                            new_harmonies.insert(m);
   634	                        }
   635	                        // Keep the input + harmonies + ports together so we
   636	                        // can route attacks correctly. Index 0 of harm_midis
   637	                        // is unused (input is at result[0]); we store the
   638	                        // full result for routing.
   639	                        let full_midis: Vec<u8> = result.iter().map(|n| u8::from(*n)).collect();
   640	                        per_input.push((full_midis, port_map));
   641	                    }
   642	                }
   643	            }
   644	
   645	            let to_release: Vec<u8> = old_harmonies.difference(&new_harmonies).copied().collect();
   646	            let to_attack: HashSet<u8> =
   647	                new_harmonies.difference(&old_harmonies).copied().collect();
   648	
   649	            // Send NoteOff for released notes — synth + every external
   650	            // port via the shared broadcast helper.
   651	            let num_ports = output_router.connection_count();
   652	            for n in &to_release {
   653	                broadcast_note_off(*n, num_ports, &synth_tx, &mut output_router);
   654	            }
   655	
   656	            // Send NoteOn for newly-attacked notes, routed per voice via
   657	            // each replay's port map and the live voice_outputs table.
   658	            let voice_targets: Vec<VoiceOutputTarget> = voice_outputs
   659	                .lock()
   660	                .unwrap_or_else(|e| e.into_inner())
   661	                .clone();
   662	            for (midis, port_map) in &per_input {
   663	                // Skip index 0 — that's the user's input note, already
   664	                // sounding from when they pressed the key. Channel 0
   665	                // and velocity 100 are reharm-path defaults (engine
   666	                // doesn't track per-input channel/velocity through
   667	                // take_reharm_inputs); same as the to_release loop
   668	                // above.
   669	                for (i, &n) in midis.iter().enumerate().skip(1) {
   670	                    if !to_attack.contains(&n) {
   671	                        continue; // already sounding from before
   672	                    }
   673	                    let slot = port_map.get(i).copied().unwrap_or(i);
   674	                    let target = voice_targets.get(slot).copied().unwrap_or_default();
   675	                    dispatch_voice(
   676	                        target,
   677	                        MIX_HARMONY,
   678	                        0,
   679	                        VoiceDispatch::NoteOn {
   680	                            note: n,
   681	                            velocity: 100,
   682	                        },
   683	                        num_ports,
   684	                        &synth_tx,
   685	                        &mut output_router,
   686	                    );
   687	                }
   688	            }
   689	
   690	            // Replace UI tracking sets with the new harmony state. Input
   691	            // notes stay as-is — user's still holding them.
   692	            {
   693	                let mut h = harmony_notes.lock().unwrap_or_else(|e| e.into_inner());
   694	                *h = new_harmonies;
   695	            }
   696	            {
   697	                let mut b = borrowed_notes.lock().unwrap_or_else(|e| e.into_inner());
   698	                b.clear();
   699	            }
   700	
   701	            // Rebuild routing-aware tracking from the replay results.
   702	            // Each input's harmonies (skipping i=0, the input itself)
   703	            // get re-keyed with their freshly-resolved per-voice
   704	            // target. Pattern attacks/releases on subsequent ticks
   705	        }
   706	
   707	        // Apply detune as MIDI pitch bend when the value changes.
   708	        let current_detune = detune_cents.load(Ordering::Relaxed);
   709	        if current_detune != prev_detune_cents {
   710	            prev_detune_cents = current_detune;
