 885		/**
 886		 * Start guitar audio capture with pitch detection.
 887		 * Routes detected notes through the harmony engine via injectNoteOn/Off.
 888		 */
 889		private async startGuitarCapture(outputIndices: number[]): Promise<void> {
 890			if (this.guitarCapture) await this.stopRoutingNow();
 891			this._guitarOutputIndices = outputIndices.slice();
 892			// Resolve MIDI outputs for sending harmony notes
 893			const access = this.ensureMidiAccess();
 894			if (access) {
 895				const outputs = Array.from(access.outputs.values());
 896				this.activeOutputs = outputIndices
 897					.filter((i) => i >= 0 && i < outputs.length)
 898					.map((i) => outputs[i]);
 899			}
 900	
 901			const capture = new GuitarAudioCapture();
 902			this.applyGuitarConfig(capture);
 903			const self = this;
 904	
 905			// Set initial gate values from store (noise gate only)
 906			capture.noiseGateThreshold = guitar.noiseGateThreshold;
 907			capture.noiseGateEnabled = guitar.noiseGateEnabled;
 908			capture.clarityGateEnabled = false;
 909	
 910			// Read device/channel directly from guitar store (not stale adapter properties)
 911			// because the user may have changed settings after the last syncDevice() call
 912			const deviceId = guitar.selectedDeviceId || this._guitarDeviceId;
 913			const channelIndex = Math.max(0, guitar.selectedChannel - 1); // 1-indexed → 0-indexed
 914			console.log(`[wasm] startGuitarCapture: device='${deviceId}' channel=${channelIndex} (store.selectedChannel=${guitar.selectedChannel})`);
 915	
 916			try {
 917				await capture.start(
 918				deviceId,
 919				channelIndex,
 920				{
 921					onNoteOn(note: number, velocity: number) {
 922						self.injectNoteOn(note, velocity).catch(() => {});
 923					},
 924					onNoteOff(note: number) {
 925						self.injectNoteOff(note).catch(() => {});
 926					},
 927					// Harmony injection emits browser MIDI on channel 0, so expression
 928					// follows that shipping channel rather than the detector's MPE channel.
 929					onPitchBend(_channel, cents) {
 930						const value = self.centsToPitchBend(cents);
 931						self.sendGuitarMidi([0xe0, value & 0x7f, (value >> 7) & 0x7f]);
 932					},
 933					onMidiPitchBend(_channel, value) {
 934						self.sendGuitarMidi([0xe0, value & 0x7f, (value >> 7) & 0x7f]);
 935					},
 936					onCC(_channel, controller, value) {
 937						self.sendGuitarMidi([0xb0, controller & 0x7f, value & 0x7f]);
 938					},
 939					onChannelPressure(_channel, pressure) {
 940						self.sendGuitarMidi([0xd0, pressure & 0x7f]);
 941					},
 942					onDetection(info) {
 943						// Sync noise gate + actual channel from capture every frame.
 944						capture.noiseGateThreshold = guitar.noiseGateThreshold;
 945						capture.noiseGateEnabled = guitar.noiseGateEnabled;
 946						guitar.activeChannel = capture.actualChannel + 1;
 947	
 948						// Push signal data for graphs
 949						guitar.pushSignalFrame(info.rms, info.clarity);
 950	
 951						if (info.frequency !== null) {
 952							guitar.currentNote = info.noteName;
 953							guitar.confidence = Math.round(info.clarity * 100);
 954							guitar.velocity = Math.round(info.rms * 800);
 955						} else {
 956							guitar.currentNote = '';
 957							guitar.confidence = 0;
 958						}
 959					}
 960				},
 961				this._guitarConfig.latencyMs
 962				);
 963			} catch (error) {
 964				await capture.stop();
 965				throw error;
 966			}
 967	
 968			// Publish only a capture whose AudioContext and stream started successfully.
 969			this.guitarCapture = capture;
 970			guitar.detecting = true;
 971			guitar.activeChannel = capture.actualChannel + 1; // 1-indexed for display
 972			this._isRunning = true;
 973			this.startNotePolling();
 974		}
