 976		private async stopRoutingNow(): Promise<void> {
 977			// Stop guitar audio capture if active
 978			if (this.guitarCapture) {
 979				await this.guitarCapture.stop();
 980				this.guitarCapture = null;
 981				guitar.detecting = false;
 982				guitar.currentNote = '';
 983				guitar.confidence = 0;
 984				guitar.velocity = 0;
 985			}
 986	
 987			// Send All-Notes-Off (CC 123) to every active output to prevent stuck notes
 988			for (const output of this.activeOutputs) {
 989				try {
 990					output.send([0xb0, 123, 0]); // CC#123 = All Notes Off
 991				} catch {
 992					// Output may already be disconnected
 993				}
 994			}
 995	
 996			// Clear engine's tracked note state
 997			if (engine) {
 998				try {
 999					engine.clear_notes();
1000				} catch {
1001					// Engine may not be initialized
1002				}
1003			}
1004	
1005			embedAudio.allNotesOff();
1006			clearCompanionNotes();
1007			try {
1008				companion?.reset_runtime?.();
1009			} catch {
1010				/* Companion may not be initialized */
1011			}
1012	
1013			// Disconnect MIDI input handler
1014			if (this.activeInput) {
1015				this.activeInput.onmidimessage = null;
1016				this.activeInput = null;
1017			}
1018			this.activeOutputs = [];
1019			this._isRunning = false;
1020			this.stopNotePolling();

