  1088		async injectNoteOn(note: number, velocity?: number): Promise<number[]> {
  1089			this.ensureInit();
  1090			try {
  1091				const result = engine.note_on(note);
  1092				const sorted = this.sortVoices(result ?? [note]);
  1093				const vel = velocity ?? 100;
  1094				for (let i = 0; i < sorted.length; i++) {
  1095					if (this.activeOutputs.length > 0) {
  1096						this.activeOutputs[i % this.activeOutputs.length].send([0x90, sorted[i], vel]);
  1097					}
  1098					// Web Audio synth — gives the browser path audible
  1099					// playback even without a connected MIDI output device
  1100					// (the desktop Tauri side has its own Rust synth).
  1101					embedAudio.noteOn(sorted[i], vel);
  1102				}
