  1104				// Counterpoint lanes can fire delayed / subdivided
  1105				// emissions. Immediate-fire ops (Species 1 at delay 0) come
  1106				// back here; longer-delayed ones drain via the tick loop.
  1107				if (companion) {
  1108					try {
  1109						const opsJson = companion.on_note_on(note, vel, 0);
  1110						this.dispatchOpsJson(opsJson);
  1111						logCompanionEvent('note_on (virtual)', {
  1112							player_note: note,
  1113							velocity: vel,
  1114							immediate_ops: this.safeParse(opsJson)
  1115						});
  1116					} catch {
  1117						/* ignore — companion is best-effort in browser */
  1118					}
  1119				}
  1120				return sorted;
  1121			} catch {
  1122				return [note];
  1123			}
  1124		}
