  1017	fn handle_note_on(
  1018	    channel: Channel,
  1019	    note: Note,
  1020	    velocity: Velocity,
  1021	    engine: &mut HarmonyEngine,
  1022	    output: &mut OutputRouter,
  1023	    input_notes: &Arc<Mutex<HashSet<u8>>>,
  1024	    harmony_notes: &Arc<Mutex<HashSet<u8>>>,
  1025	    borrowed_notes: &Arc<Mutex<HashSet<u8>>>,
  1026	    chord_name: &Arc<Mutex<String>>,
  1027	    routing_mode: contrapunk::harmony::RoutingMode,
  1028	    synth_tx: &mpsc::Sender<SynthEvent>,
  1029	    voice_outputs: &Arc<Mutex<Vec<VoiceOutputTarget>>>,
  1030	) {
  1031	    let notes = engine.harmonize_note_on(note);
  1032	    // Drain any harmonies the engine flagged for explicit release —
  1033	    // populated when an auto-key change wiped `active_notes` mid-flight.
  1034	    // These would otherwise stay sounding under the old key.
  1035	    let stale_releases = engine.take_pending_releases();
  1036	    let num_outputs = output.connection_count();
  1037	
  1038	    // Send Note-Offs for stale harmonies before emitting the new ones.
  1039	    if !stale_releases.is_empty() {
  1040	        for &n in &stale_releases {
  1041	            broadcast_note_off(u8::from(n), num_outputs, synth_tx, output);
  1042	        }
  1043	        let mut harm = harmony_notes.lock().unwrap_or_else(|e| e.into_inner());
  1044	        let mut borr = borrowed_notes.lock().unwrap_or_else(|e| e.into_inner());
  1045	        for &n in &stale_releases {
  1046	            harm.remove(&u8::from(n));
  1047	            borr.remove(&u8::from(n));
  1048	        }
  1049	    }
  1050	
  1051	    // Snapshot voice routing once per note event — clone is cheap
  1052	    // (8-element Vec of Copy enums) and avoids lock contention during
  1053	    // dispatch.
  1054	    let voice_targets: Vec<VoiceOutputTarget> = voice_outputs
  1055	        .lock()
  1056	        .unwrap_or_else(|e| e.into_inner())
  1057	        .clone();
  1058	    // The harmony engine returns notes as `[input, closest_harmony, ...]`
  1059	    // — input always at index 0. To route each entry to the correct
  1060	    // SATB voice slot (so e.g. the user's note plays through the
  1061	    // tenor's output target when voice_position=2), we map result-Vec
  1062	    // index → arrangement slot via the engine's port map.
  1063	    let port_map: Vec<usize> = engine.last_port_map().to_vec();
  1064	    let target_for = |i: usize| -> VoiceOutputTarget {
  1065	        let slot = port_map.get(i).copied().unwrap_or(i);
  1066	        voice_targets.get(slot).copied().unwrap_or_default()
  1067	    };
  1068	
  1069	    // Fan each voice via the unified dispatch helper. Synth and
  1070	    // external MIDI go in one loop; `dispatch_voice` handles the
  1071	    // target.match cases internally. Order: dispatch first so the
  1072	    // synth's audible NoteOn precedes the tracking-set updates that
  1073	    // chord-display reads from (chord display tolerates briefly
  1074	    // stale state better than humans tolerate audible latency).
  1075	    let channel_idx: u8 = channel.index();
  1076	    let velocity_byte: u8 = u8::from(velocity);
  1077	    for (i, &n) in notes.iter().enumerate() {
  1078	        dispatch_voice(
  1079	            target_for(i),
  1080	            if i == 0 { MIX_INPUT } else { MIX_HARMONY },
  1081	            channel_idx,
  1082	            VoiceDispatch::NoteOn {
  1083	                note: u8::from(n),
  1084	                velocity: velocity_byte,
  1085	            },
  1086	            num_outputs,
  1087	            synth_tx,
  1088	            output,
  1089	        );
  1090	    }
  1091	
  1092	    // Update shared state — recover from poisoned mutexes rather than panic.
  1093	    {
  1094	        let mut in_notes = input_notes.lock().unwrap_or_else(|e| e.into_inner());
  1095	        in_notes.insert(note as u8);
  1096	    }
  1097	    {
  1098	        let mut harm_notes = harmony_notes.lock().unwrap_or_else(|e| e.into_inner());
  1099	        for &n in notes.iter().skip(1) {
  1100	            harm_notes.insert(n as u8);
  1101	        }
  1102	    }
  1103	    if engine.last_borrowed_from().is_some() {
  1104	        let mut borr = borrowed_notes.lock().unwrap_or_else(|e| e.into_inner());
  1105	        for &n in notes.iter().skip(1) {
  1106	            borr.insert(n as u8);
  1107	        }
  1108	    }
  1109	
  1110	    {
  1111	        let all_sounding: HashSet<u8> = {
  1112	            let in_notes = input_notes.lock().unwrap_or_else(|e| e.into_inner());
  1113	            let harm_notes = harmony_notes.lock().unwrap_or_else(|e| e.into_inner());
  1114	            in_notes.union(&harm_notes).copied().collect()
  1115	        };
  1116	        if !all_sounding.is_empty() {
  1117	            let key_tonic = Some(engine.key().semitones_from_c());
  1118	            let display = chord_display_with_analysis(&all_sounding, key_tonic);
  1119	            let mut ch = chord_name.lock().unwrap_or_else(|e| e.into_inner());
  1120	            *ch = display;
  1121	        }
  1122	    }
  1123	
  1124	    let _ = (channel_idx, velocity_byte, target_for);
  1125	}
