  1169	            VoiceDispatch::NoteOff {
  1170	                note: u8::from(n),
  1171	                velocity: velocity_byte,
  1172	            },
  1173	            num_outputs,
  1174	            synth_tx,
  1175	            output,
  1176	        );
  1177	    }
