     1	//! WASM bridge for the shared Companion orchestrator.
     2	//!
     3	//! Exposes a thin `CompanionWasm` wrapper around
     4	//! `contrapunk_companion::Companion` so the browser build can host
     5	//! both lanes (Canon + Counterpoint) that ship in v1.2.0. The JS
     6	//! adapter feeds player NoteOn / NoteOff via `on_note_on` /
     7	//! `on_note_off`, ticks the lanes via `tick(beat)`, and reads back
     8	//! dispatch ops as JSON to schedule on the WebAudio synth.
     9	//!
    10	//! The Companion's internal mini-engines need a HarmonyEngine
    11	//! snapshot to mirror global key/scale/mode state. In Tauri that
    12	//! snapshot lives in `WorldState::engine_snapshot` and is shared with
    13	//! the router thread's main engine. In WASM there's no router thread;
    14	//! the JS side calls `set_global_state(...)` after each user change
    15	//! to mirror the same fields into the snapshot.
    16	
    17	use std::sync::{Arc, Mutex};
    18	
    19	use wasm_bindgen::prelude::*;
    20	use wmidi::Note;
    21	
    22	use contrapunk_companion::lane::InputEvent;
    23	use contrapunk_companion::{CanonLane, CounterpointLane, PatternLane};
    24	use contrapunk_companion::{Companion, DispatchOp, WorldState};
    25	use contrapunk_harmony::{HarmonyEngine, HarmonyMode, Key};
    26	use contrapunk_transport::Transport;
    27	
    28	use crate::enum_strings::{parse_key, parse_mode, parse_scale_mode};
    29	
    30	#[wasm_bindgen]
    31	pub struct CompanionWasm {
    32	    inner: Companion,
    33	    world: Arc<WorldState>,
    34	    /// Unused "main engine" passed into Companion::tick — the canon
    35	    /// and counterpoint lanes are both Decide-phase and don't mutate
    36	    /// the main engine, so this is a no-op recipient.
    37	    dummy_engine: Mutex<HarmonyEngine>,
    38	}
    39	
    40	#[wasm_bindgen]
    41	impl CompanionWasm {
    42	    #[wasm_bindgen(constructor)]
    43	    pub fn new() -> Self {
    44	        let transport = Transport::new(48_000);
    45	        // Snapshot engine the Companion's mini-engines read for global
    46	        // key/mode/scale defaults. JS keeps this in sync via
    47	        // set_global_* setters below.
    48	        let engine = Arc::new(Mutex::new(HarmonyEngine::new(
    49	            Key::C,
    50	            HarmonyMode::PassThrough,
    51	        )));
    52	        let world = WorldState::new(Arc::clone(&transport), Arc::clone(&engine));
    53	        let mut companion = Companion::new(world.clone());
    54	        companion.lanes.push(Box::new(CanonLane::new()));
    55	        companion.lanes.push(Box::new(CounterpointLane::new()));
    56	        companion
    57	            .lanes
    58	            .push(Box::new(PatternLane::new("Low Support", "pattern_low")));
    59	        companion.lanes.push(Box::new(PatternLane::new(
    60	            "Counterline Pattern",
    61	            "pattern_counter",
    62	        )));
    63	        // Master enable defaults ON to match the Tauri build's FTUX.
    64	        companion
    65	            .enabled
    66	            .store(true, std::sync::atomic::Ordering::Release);
    67	
    68	        Self {
    69	            inner: companion,
    70	            world,
    71	            dummy_engine: Mutex::new(HarmonyEngine::new(Key::C, HarmonyMode::PassThrough)),
    72	        }
    73	    }
    74	
    75	    #[wasm_bindgen]
    76	    pub fn set_enabled(&self, enabled: bool) {
    77	        self.inner
    78	            .enabled
    79	            .store(enabled, std::sync::atomic::Ordering::Release);
    80	    }
    81	
    82	    #[wasm_bindgen]
    83	    pub fn is_enabled(&self) -> bool {
    84	        self.inner
    85	            .enabled
    86	            .load(std::sync::atomic::Ordering::Acquire)
    87	    }
    88	
    89	    /// Mirror the global engine's key/scale/mode/voice_count etc.
    90	    /// into the snapshot the Companion's mini-engines read. Called by
    91	    /// JS whenever the Harmony tab changes these.
    92	    #[wasm_bindgen]
    93	    pub fn set_global_state(
    94	        &self,
    95	        key: &str,
    96	        mode: &str,
    97	        scale_mode: &str,
    98	        voice_count: usize,
    99	        voice_position: usize,
   100	    ) -> Result<(), JsValue> {
   101	        let key = parse_key(key)?;
   102	        let mode = parse_mode(mode)?;
   103	        let scale_mode = parse_scale_mode(scale_mode)?;
   104	        let mut eng = self
   105	            .world
   106	            .engine_snapshot
   107	            .lock()
   108	            .map_err(|e| JsValue::from_str(&format!("snapshot lock: {}", e)))?;
   109	        if eng.key() != key {
   110	            eng.set_key(key);
   111	        }
   112	        if eng.mode() != mode {
   113	            eng.set_mode(mode);
   114	        }
   115	        if eng.scale_mode() != scale_mode {
   116	            eng.set_scale_mode(scale_mode);
   117	        }
   118	        if eng.voice_count() != voice_count {
   119	            eng.set_voice_count(voice_count);
   120	        }
   121	        if eng.voice_position() != voice_position {
   122	            eng.set_voice_position(voice_position);
   123	        }
   124	        Ok(())
   125	    }
   125	    }
   126	
   127	    /// Apply a partial JSON state blob to the canon lane (same shape
   128	    /// the Tauri command consumes). See CanonLane::deserialize_state.
   129	    #[wasm_bindgen]
   130	    pub fn configure_canon(&mut self, json: &str) -> Result<(), JsValue> {
   131	        let value: serde_json::Value =
   132	            serde_json::from_str(json).map_err(|e| JsValue::from_str(&e.to_string()))?;
   133	        self.inner
   134	            .configure_lane("canon", value)
   135	            .map_err(|e| JsValue::from_str(&e))
   136	    }
   137	
   138	    #[wasm_bindgen]
   139	    pub fn configure_counterpoint(&mut self, json: &str) -> Result<(), JsValue> {
   140	        let value: serde_json::Value =
   141	            serde_json::from_str(json).map_err(|e| JsValue::from_str(&e.to_string()))?;
   142	        self.inner
   143	            .configure_lane("counterpoint", value)
   144	            .map_err(|e| JsValue::from_str(&e))
   145	    }
   146	
   147	    #[wasm_bindgen]
   148	    pub fn configure_pattern(&mut self, lane_id: &str, json: &str) -> Result<(), JsValue> {
   149	        if !matches!(lane_id, "pattern_low" | "pattern_counter") {
   150	            return Err(JsValue::from_str("unknown pattern lane"));
   151	        }
   152	        let value: serde_json::Value =
   153	            serde_json::from_str(json).map_err(|e| JsValue::from_str(&e.to_string()))?;
   154	        self.inner
   155	            .configure_lane(lane_id, value)
   156	            .map_err(|e| JsValue::from_str(&e))
   157	    }
   158	
   159	    /// Set the Companion's global HoldMode default. JSON shape:
   160	    ///   {"kind":"cancel"}
   161	    ///   {"kind":"near_future","tail_beats":1.0}
   162	    ///   {"kind":"phrase_end"}
   163	    ///   {"kind":"forever"}
   164	    /// Lanes / voices can still override via the existing
   165	    /// `configure_canon` / `configure_counterpoint` JSON paths (they
   166	    /// each accept a `hold_mode` field with the same shape).
   167	    #[wasm_bindgen]
   168	    pub fn pattern_state(&self, lane_id: &str) -> Result<String, JsValue> {
   169	        if !matches!(lane_id, "pattern_low" | "pattern_counter") {
   170	            return Err(JsValue::from_str("unknown pattern lane"));
   171	        }
   172	        Ok(self
   173	            .inner
   174	            .lane_state(lane_id)
   175	            .unwrap_or(serde_json::Value::Null)
   176	            .to_string())
   177	    }
   178	
   179	    #[wasm_bindgen]
   180	    pub fn set_global_hold_mode(&self, json: &str) -> Result<(), JsValue> {
   181	        let value: serde_json::Value =
   182	            serde_json::from_str(json).map_err(|e| JsValue::from_str(&e.to_string()))?;
   183	        let mode = contrapunk_companion::lane::hold_mode_from_json(&value)
   184	            .ok_or_else(|| JsValue::from_str("invalid hold_mode JSON shape"))?;
   185	        self.inner.set_global_hold_mode(mode);
   186	        Ok(())
   187	    }
   188	
   189	    /// Advance the transport by `frames` audio frames. JS calls this
   190	    /// from its animation-frame / WebAudio loop so per-lane scheduling
   191	    /// (canon delays, counterpoint subdivisions) sees forward time.
   192	    /// At the default 48 kHz sample rate, 768 frames ≈ 16 ms.
   193	    #[wasm_bindgen]
   194	    pub fn advance(&self, frames: u32) {
   195	        if !self.world.transport.is_running() {
   196	            self.world.transport.play();
   197	        }
   198	        let _ = self.world.transport.advance(frames);
   199	    }
   200	
   201	    /// Feed a player NoteOn into the Companion. Returns a JSON array
   202	    /// of dispatch ops emitted by lanes that fired immediately
   203	    /// (Species 1 canon-onset emissions, etc.). Each op carries a
   204	    /// `lane` field (e.g. `"canon"`, `"counterpoint"`) so the UI can
   205	    /// render per-lane attribution (different piano colors per lane).
   206	    #[wasm_bindgen]
   207	    pub fn on_note_on(&mut self, note: u8, velocity: u8, channel: u8) -> Result<String, JsValue> {
   208	        let ev = InputEvent::NoteOn {
   209	            note,
   210	            velocity,
   211	            channel,
   212	        };
   213	        let (tagged, _suppress) = self.inner.on_input_tagged(ev, &self.dummy_engine);
   214	        serialize_tagged_ops(&tagged).map_err(|e| JsValue::from_str(&e.to_string()))
   215	    }
   216	
   217	    #[wasm_bindgen]
   218	    pub fn on_note_off(&mut self, note: u8, channel: u8) -> Result<String, JsValue> {
   219	        let ev = InputEvent::NoteOff { note, channel };
   220	        let (tagged, _suppress) = self.inner.on_input_tagged(ev, &self.dummy_engine);
