   639	/// Convert a MIDI note number (0-127) to its note name (e.g. 60 -> "C4").
   640	#[wasm_bindgen]
   641	pub fn midi_to_name(midi: u8) -> String {
   642	    let note_names = [
   643	        "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B",
   644	    ];
   645	    let octave = (midi as i8 / 12) - 1;
   646	    let name_idx = (midi % 12) as usize;
   647	    format!("{}{}", note_names[name_idx], octave)
   648	}
