   650	#[cfg(test)]
   651	mod tests {
   652	    use super::*;
   653	    use contrapunk::harmony::{CounterpointSpecies, CounterpointStrictness};
   654	
   655	    /// Every species name that the UI sends must parse back to the matching
   656	    /// `CounterpointSpecies` variant. This is the bridge-layer smoke test:
   657	    /// if the UI string contract drifts, this catches it at build time.
   658	    #[test]
   659	    fn test_counterpoint_species_roundtrip() {
   660	        let cases = [
   661	            ("Species1", CounterpointSpecies::Species1),
   662	            ("Species2", CounterpointSpecies::Species2),
   663	            ("Species3", CounterpointSpecies::Species3),
   664	            ("Species4", CounterpointSpecies::Species4),
   665	        ];
   666	        for (name, expected) in cases {
   667	            let parsed = parse_counterpoint_species(name)
   668	                .unwrap_or_else(|_| panic!("should parse {}", name));
   669	            assert_eq!(parsed, expected);
   670	            // And the reverse direction: enum -> string the UI expects back.
   671	            assert_eq!(counterpoint_species_to_string(expected), name);
   672	        }
   673	    }
   674	
   675	    #[test]
   676	    fn test_counterpoint_strictness_roundtrip() {
   677	        let cases = [
   678	            ("Relaxed", CounterpointStrictness::Relaxed),
   679	            ("Strict", CounterpointStrictness::Strict),
