     1	/**
     2	 * Shared "composite Mode dropdown" helper.
     3	 *
     4	 * The Mode picker in the Harmony tab, the per-voice Mode picker in
     5	 * the Companion's canon voice cards, and the Mode picker in the
     6	 * Voices tab editor all expose the same thing: the harmony-engine
     7	 * modes, with Counterpoint expanded into its four Fux species. Picking
     8	 * a Counterpoint variant sets BOTH the harmony_mode and the species
     9	 * in one click; everything else just sets the mode. Strictness is
    10	 * always 'Strict' — no Relaxed control surfaced.
    11	 *
    12	 * Encoding: plain modes use their canonical name (`PassThrough`,
    13	 * `BachChorale`, …). Counterpoint variants encode as
    14	 * `StrictCounterpoint:SpeciesN`. This file is the single source of
    15	 * truth for that wire format — callers should NEVER duplicate the
    16	 * split/join logic.
    17	 */
    18	import {
    19		ALL_MODES,
    20		type CounterpointSpeciesName,
    21		type HarmonyModeName
    22	} from '$lib/stores/engine.svelte';
    23	import { formatMusicalString } from '$lib/embed/music-utils';
    24	
    25	export interface CompositeModeOption {
    26		value: string;
    27		label: string;
    28	}
    29	
    30	/** Build the dropdown options. Counterpoint expands to 4 species
    31	 *  entries; every other mode keeps its single entry. `labelFormatter`
    32	 *  defaults to `formatMusicalString` (used by the Harmony tab); pass
    33	 *  identity to keep the raw mode label. */
    34	export function compositeModeOptions(
    35		labelFormatter: (s: string) => string = formatMusicalString
    36	): CompositeModeOption[] {
    37		return ALL_MODES.flatMap((m) => {
    38			const display = labelFormatter(m.label);
    39			if (m.name === 'StrictCounterpoint') {
    40				return [
    41					{ value: 'StrictCounterpoint:Species1', label: `${display} (1:1)` },
    42					{ value: 'StrictCounterpoint:Species2', label: `${display} (2:1 rules)` },
    43					{ value: 'StrictCounterpoint:Species3', label: `${display} (4:1 rules)` },
    44					{ value: 'StrictCounterpoint:Species4', label: `${display} (syncopated rules)` }
    45				];
    46			}
    47			return [{ value: m.name, label: display }];
    48		});
    49	}
    50	
    51	/** Encode (harmony_mode, counterpoint_species) → composite dropdown
    52	 *  value. Counterpoint without a species defaults to Species1. Empty
    53	 *  mode returns `''` (inherit / unset). */
    54	export function encodeMode(
    55		mode: HarmonyModeName | string | null | undefined,
    56		species: CounterpointSpeciesName | string | null | undefined
    57	): string {
    58		if (!mode) return '';
    59		if (mode === 'StrictCounterpoint') {
    60			return `StrictCounterpoint:${species ?? 'Species1'}`;
    61		}
    62		return mode;
    63	}
    64	
    65	/** Decode a composite dropdown value back into the pair. Counterpoint
    66	 *  values produce `{mode: 'StrictCounterpoint', species: 'SpeciesN'}`;
    67	 *  plain modes produce `{mode, species: null}`; empty string
    68	 *  produces `{mode: null, species: null}`. */
    69	export function decodeMode(v: string): {
    70		mode: HarmonyModeName | null;
    71		species: CounterpointSpeciesName | null;
    72	} {
    73		if (!v) return { mode: null, species: null };
    74		if (v.startsWith('StrictCounterpoint:')) {
    75			return {
    76				mode: 'StrictCounterpoint' as HarmonyModeName,
    77				species: v.slice('StrictCounterpoint:'.length) as CounterpointSpeciesName
    78			};
    79		}
    80		return { mode: v as HarmonyModeName, species: null };
    81	}
