     1	<script lang="ts">
     2		import { voiceLibrary, type VoicePreset } from '$lib/stores/voiceLibrary.svelte';
     3		import {
     4			ALL_MODES,
     5			OCTAVE_MODES,
     6			SCALE_FAMILIES,
     7			VOICE_LEADING_STYLES
     8		} from '$lib/stores/engine.svelte';
     9		import {
    10			compositeModeOptions,
    11			encodeMode as encodeCompositeMode,
    12			decodeMode as decodeCompositeMode
    13		} from '$lib/harmony/modeComposite';
    14		import PixelSelect from './PixelSelect.svelte';
    15	
    16		let selectedId = $state<string | null>(voiceLibrary.all[0]?.id ?? null);
    17		let creating = $state(false);
    18		let newName = $state('');
    19	
    20		let selected = $derived(
    21			selectedId ? voiceLibrary.byId(selectedId) ?? null : null
    22		);
    23	
    24		// Cloneable "scratch" preset shown in the editor — never mutates a
    25		// built-in. For user presets the patch flows back through update().
    26		let editorState = $state<Omit<VoicePreset, 'id' | 'builtIn'>>(emptyEditor());
    27	
    28		function emptyEditor(): Omit<VoicePreset, 'id' | 'builtIn'> {
    29			return {
    30				name: 'New Voice',
    31				harmony_mode: 'StrictCounterpoint',
    32				scale_mode: 'Ionian',
    33				voice_leading_enabled: true,
    34				voice_leading_style: 'Palestrina',
    35				octave_mode: 'Spread',
    36				counterpoint_species: 'Species1',
    37				counterpoint_strictness: 'Strict',
    38				voice_count: 4,
    39				voice_position: 3
    40			};
    41		}
    42	
    43		// Sync editorState whenever selection changes.
    44		$effect(() => {
    45			if (selected) {
    46				editorState = {
    47					name: selected.name,
    48					harmony_mode: selected.harmony_mode,
    49					scale_mode: selected.scale_mode,
    50					voice_leading_enabled: selected.voice_leading_enabled,
    51					voice_leading_style: selected.voice_leading_style,
    52					octave_mode: selected.octave_mode,
    53					counterpoint_species: selected.counterpoint_species,
    54					counterpoint_strictness: selected.counterpoint_strictness,
    55					voice_count: selected.voice_count,
    56					voice_position: selected.voice_position
    57				};
    58			}
    59		});
    60	
    61		function applyEditorToSelected() {
    62			if (!selected || selected.builtIn) return;
    63			voiceLibrary.update(selected.id, editorState);
    64		}
    65	
    66		function createPreset() {
    67			const name = newName.trim();
    68			if (!name) return;
    69			const id = voiceLibrary.create({ ...emptyEditor(), name });
    70			selectedId = id;
    71			creating = false;
    72			newName = '';
    73		}
    74	
    75		function deleteSelected() {
    76			if (!selected || selected.builtIn) return;
    77			const id = selected.id;
    78			const all = voiceLibrary.all;
    79			const idx = all.findIndex((p) => p.id === id);
    80			voiceLibrary.delete(id);
    81			// Move selection to a neighbouring preset.
    82			const remaining = voiceLibrary.all;
    83			selectedId = remaining[Math.min(idx, remaining.length - 1)]?.id ?? null;
    84		}
    85	
    86		function duplicateSelected() {
    87			if (!selected) return;
    88			const copy = {
    89				name: `${selected.name} (copy)`,
    90				harmony_mode: selected.harmony_mode,
    91				scale_mode: selected.scale_mode,
    92				voice_leading_enabled: selected.voice_leading_enabled,
    93				voice_leading_style: selected.voice_leading_style,
    94				octave_mode: selected.octave_mode,
    95				counterpoint_species: selected.counterpoint_species,
    96				counterpoint_strictness: selected.counterpoint_strictness,
    97				voice_count: selected.voice_count,
    98				voice_position: selected.voice_position
    99			};
   100			const id = voiceLibrary.create(copy);
   101			selectedId = id;
   102		}
   103	
   104		// Shared composite-mode dropdown options + encode/decode (same as
   105		// Harmony tab and Companion). Pass identity formatter to keep the
   106		// raw mode label without musical-symbol substitution.
   107		const COMPOSITE_MODE_OPTIONS = compositeModeOptions((s) => s);
   108		const SCALE_MODE_OPTIONS = SCALE_FAMILIES.flatMap((f) =>
   109			f.modes.map((m) => ({ value: m.name, label: `${f.label} · ${m.label}` }))
   110		);
   111		const VL_STYLE_OPTIONS = VOICE_LEADING_STYLES.map((s) => ({
   112			value: s.name,
   113			label: s.label
   114		}));
   115		const OCTAVE_MODE_OPTIONS = OCTAVE_MODES.map((m) => ({
   116			value: m.name,
   117			label: m.label
   118		}));
   119	</script>
   120	
   121	<div class="voices-root">
   122		<header class="header">
   123			<div class="header-left">
   124				<h2 class="title font-ui">Voices</h2>
   125				<span class="subtitle font-code">
   126					named harmony presets · pick from the Companion's Relative + Mode picker
   127				</span>
   128			</div>
   129		</header>
   130	
   300								onchange={(v) => {
   301									editorState.octave_mode = v as typeof editorState.octave_mode;
   302									applyEditorToSelected();
   303								}}
   304							/>
   305						</label>
   306	
   307						<label class="row">
   308							<span class="row-label font-ui">Voice Count</span>
   309							<input
