   311								min="1"
   312								max="4"
   313								class="pixel-input num"
   314								bind:value={editorState.voice_count}
   315								disabled={selected.builtIn}
   316								onchange={applyEditorToSelected}
   317							/>
   318						</label>
   319	
   320						<label class="row">
   321							<span class="row-label font-ui">Voice Position</span>
   322							<input
