    53					counterpoint_species: selected.counterpoint_species,
    54					counterpoint_strictness: selected.counterpoint_strictness,
    55					voice_count: selected.voice_count,
    56					voice_position: selected.voice_position
    57				};
    58			}
    59		});
    60	
    61		function applyEditorToSelected() {
    62			if (!selected || selected.builtIn) return;
    63			voiceLibrary.update(selected.id, editorState);
    64		}
    65	
    66		function createPreset() {
    67			const name = newName.trim();
    68			if (!name) return;
    69			const id = voiceLibrary.create({ ...emptyEditor(), name });
    70			selectedId = id;
    71			creating = false;
    72			newName = '';
    73		}
    74	
    75		function deleteSelected() {
    76			if (!selected || selected.builtIn) return;
    77			const id = selected.id;
    78			const all = voiceLibrary.all;
    79			const idx = all.findIndex((p) => p.id === id);
    80			voiceLibrary.delete(id);
    81			// Move selection to a neighbouring preset.
    82			const remaining = voiceLibrary.all;
    83			selectedId = remaining[Math.min(idx, remaining.length - 1)]?.id ?? null;
    84		}
    85	
    86		function duplicateSelected() {
