 31	
 32		type SetupSection = 'input' | 'harmony' | 'canon' | 'counterpoint' | 'output' | 'presets' | 'advanced';
 33	
 34		const VIRTUAL_COMPUTER_KEYBOARD = 999_998;
 35		const VIRTUAL_GUITAR_AUDIO = 999_997;
 36		const scaleOptions = SCALE_FAMILIES.flatMap((family) => family.modes);
