 44		let companionFocus = $state<'imitative' | 'species'>('imitative');
 45		let companionFocusVersion = $state(0);
 46	
 47		let inputLive = $derived(engine.inputNotes.length > 0);
 48		let ensembleLive = $derived(engine.harmonyNotes.length > 0 || engine.canonNotes.length > 0 || engine.counterpointNotes.length > 0);
 49		let outputLive = $derived(inputLive || ensembleLive);
 50		let sourceName = $derived.by(() => {
 51			if (midi.selectedInput === VIRTUAL_GUITAR_AUDIO) return 'Guitar Audio';
 52			if (midi.selectedInput === VIRTUAL_COMPUTER_KEYBOARD) return 'Computer Keys';
 53			if (midi.selectedInput === null) return 'No input';
 54			return midi.inputs.find((device) => device.index === midi.selectedInput)?.name ?? 'MIDI Controller';
 55		});
 56		let spread = $derived(engine.octaveMode === 'None' ? 0 : engine.octaveIntensity);
 57		let registerOptions = $derived(
 58			Array.from({ length: engine.voiceCount }, (_, index) => ({
 59				value: index,
 60				label: engine.voiceCount <= 4 ? (['Soprano', 'Alto', 'Tenor', 'Bass'][index] ?? `Voice ${index + 1}`) : `Voice ${index + 1}`
 61			}))
 62		);
 63		let quickModes = $derived.by(() => {
 64			if (ALL_MODES.some((mode) => mode.name === engine.mode)) return ALL_MODES;
 65			return [{ name: engine.mode, label: engine.mode, shortLabel: engine.mode, tooltip: '' }, ...ALL_MODES];
 66		});
 67	
 68		onMount(() => {
 69			let cancelled = false;
 70			void (async () => {
 71				try {
 72					ui.restoreAppearance();
 73					await adapter.init();
 74					await engine.syncFromBackend();
 75					if (adapter.capabilities.pluginMidiOutputMode) await engine.restoreCompanionSettings();
 76					else await engine.restoreSettings();
 77					await midi.hydratePermission();
 78					await Promise.all([synth.syncFromBackend(), transport.syncFromBackend()]);
 79					try {
 80						await transport.setMetronomeEnabled(false);
 81					} catch {
 82						/* Surface has no transport. */
 83					}
 84					if (midi.selectedInput === null) {
 85						midi.selectVirtualInput(VIRTUAL_COMPUTER_KEYBOARD);
 86					}
 87					if (!engine.isRunning && midi.selectedInput !== null) {
 88						await engine.start(midi.selectedInput, midi.selectedOutputs);
 89					}
 90					if (!cancelled) initialized = true;
180					<label class="spread"><span>SPREAD <output>{Math.round(spread * 100)}</output></span><input type="range" min="0" max="1" step="0.01" value={spread} oninput={(event) => setSpread(Number(event.currentTarget.value))} /></label>
181				</section>
