197					<nav aria-label="Setup sections">
198						<button class:active={setupSection === 'input'} onclick={() => openSetup('input')}>01 Input</button>
199						<button class:active={setupSection === 'harmony'} onclick={() => openSetup('harmony')}>02 Harmony</button>
200						<button class:active={setupSection === 'canon' || setupSection === 'counterpoint'} onclick={() => openSetup('canon')}>03 Canon + Counterpoint</button>
201						<button class:active={setupSection === 'output'} onclick={() => openSetup('output')}>04 Output + Sound</button>
202						<button class:active={setupSection === 'presets'} onclick={() => openSetup('presets')}>05 Presets + Voices</button>
203						<button class:active={setupSection === 'advanced'} onclick={() => openSetup('advanced')}>06 Advanced</button>
204					</nav>
205					<div class="setup-scroll">
206						<section id="setup-input" tabindex="-1"><div class="section-heading"><span>01</span><h2>Input</h2></div>{#if adapter.capabilities.inputSourcePicker}<InputPanel />{:else}<div class="notice">The host owns input selection.</div>{/if}</section>
207						<section id="setup-harmony" tabindex="-1"><div class="section-heading"><span>02</span><h2>Harmony</h2></div><div id="harmony-controls">{#if setupOpen}<PerformanceView midiLearnEnabled={setupSection === 'harmony' && midi.selectedInput !== VIRTUAL_GUITAR_AUDIO} />{/if}</div>{#if adapter.capabilities.intervalMaps && engine.mode === 'ExplicitIntervals'}<ExplicitIntervalMapPanel />{/if}</section>
208						<section id="setup-canon" tabindex="-1"><div class="section-heading"><span>03</span><h2>Canon + Counterpoint</h2></div>{#if adapter.capabilities.companionLanes}<div id="canon-controls"><CompanionPanel focusGroup={companionFocus} focusVersion={companionFocusVersion} /></div>{#if adapter.capabilities.patternLanes}<PatternLanePanel />{/if}{:else}<div class="notice">Companion lanes are unavailable on this surface.</div>{/if}</section>
209						<section id="setup-output" tabindex="-1"><div class="section-heading"><span>04</span><h2>Output + Sound</h2></div><div id="output-routing"><OutputPanel /></div></section>
210						<section id="setup-presets" tabindex="-1"><div class="section-heading"><span>05</span><h2>Presets + Voices</h2></div><EnsemblePresetBar /><div class="preset-grid"><PresetManager /><VoicesPanel /></div></section>
211						<section id="setup-advanced" tabindex="-1">
212							<div class="section-heading"><span>06</span><h2>Advanced</h2></div>
213							<div class="interface-settings" aria-label="Interface preferences">
214								<label><span>Interface scale</span><input type="range" min="0.75" max="2" step="0.05" value={ui.uiScale} oninput={(event) => ui.setUiScale(Number(event.currentTarget.value))} /><output>{Math.round(ui.uiScale * 100)}%</output></label>
215								<label><span>Text scale</span><input type="range" min="0.75" max="1.5" step="0.05" value={ui.fontScale} oninput={(event) => ui.setFontScale(Number(event.currentTarget.value))} /><output>{Math.round(ui.fontScale * 100)}%</output></label>
216								<label><span>MIDI keyboard size</span><select value={ui.pianoKeyCount} onchange={(event) => ui.setPianoKeyCount(Number(event.currentTarget.value))}>{#each PIANO_KEY_COUNTS as count}<option value={count}>{count} keys</option>{/each}</select><output>{ui.pianoKeyCount}</output></label>
217								<label class="check"><input type="checkbox" checked={ui.showNoteLabels} onchange={(event) => ui.setShowNoteLabels(event.currentTarget.checked)} /><span>Show note labels</span></label>
218								<label class="check"><input type="checkbox" checked={ui.noteLingering} onchange={(event) => ui.setNoteLingering(event.currentTarget.checked)} /><span>Released-note trail</span></label>
219								<label class="check"><input type="checkbox" checked={ui.animationsEnabled} onchange={() => ui.toggleAnimations()} /><span>Interface motion</span></label>
220							</div>
221							<ControlPanel />
222						</section>
223					</div>
