 533				throw new Error(`Failed to set explicit interval map: ${e}`);
 534			}
 535		}
 536	
 500	    fn sync_voice_engines(&mut self, world: &WorldState) {
 501	        // Snapshot global state under one brief lock. Voices with
 502	        // None for an override field inherit the corresponding global.
 503	        let snapshot = if let Ok(g) = world.engine_snapshot.lock() {
 504	            EngineSnapshot {
 505	                key: g.key(),
 506	                mode: g.mode(),
 507	                scale_mode: g.scale_mode(),
 508	                explicit_interval_map: g.explicit_interval_map().clone(),
 509	                octave_mode: g.octave_mode(),
 510	                voice_count: g.voice_count(),
 511	                voice_position: g.voice_position(),
 512	                voice_leading_enabled: g.voice_leading_enabled(),
 513	                voice_leading_style: g.voice_leading_style(),
 514	                counterpoint_species: g.counterpoint_species(),
 515	                counterpoint_strictness: g.counterpoint_strictness(),
 516	                counterpoint_beat_phase: g.counterpoint_beat_phase(),
 517	            }
 518	        } else {
 519	            EngineSnapshot::default()
 520	        };
 521	
 522	        // Resize: grow with newly-constructed engines, shrink by drop.
 523	        while self.voice_engines.len() < self.voices.len() {
 524	            // Fresh engines default to the canon contract: 2 voices
 525	            // (subject + one harmony partner). Per-voice override
 526	            // applied immediately below.
 527	            self.voice_engines
 528	                .push(HarmonyEngine::with_voices(snapshot.key, snapshot.mode, 2));
 529	        }
 530	        self.voice_engines.truncate(self.voices.len());
 531	
 532	        // Sync per-voice engine config. set_* methods on
 533	        // HarmonyEngine are no-ops when the value matches, so stateful
 534	        // history only resets on real change. Order matters: voice_count
 535	        // before voice_position (the latter is clamped to count-1).
 536	        for (i, voice) in self.voices.iter().enumerate() {
 537	            let Some(ve) = self.voice_engines.get_mut(i) else {
 538	                continue;
 539	            };
 540	            if ve.key() != snapshot.key {
 541	                ve.set_key(snapshot.key);
 542	            }
 543	            if ve.scale_mode() != snapshot.scale_mode {
 544	                ve.set_scale_mode(snapshot.scale_mode);
 545	            }
 546	            if ve.explicit_interval_map() != &snapshot.explicit_interval_map {
 547	                let _ = ve.set_explicit_interval_map(snapshot.explicit_interval_map.clone());
 548	            }
 549	            let target_mode = voice.harmony_mode.unwrap_or(snapshot.mode);
 550	            if ve.mode() != target_mode {
 551	                ve.set_mode(target_mode);
 552	            }

